(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0012.js"] = [{"id":"poem-4fff21dcd2ee20bfc8c4fa0e","title":"笑轩沈仲归挽章","author":"释居简","dynasty":"宋","verses":["尊周微意托炎刘，秽史端令后世羞。","不把遗经究终始，安知吾志在春秋。","虹霓未吐身先老，龟手空传自不侯。","奏赋长杨上天去，断编残简乱山丘。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-4af5d82f-df12-4b9b-8789-4c4571d8e561","tags":[]},{"id":"poem-500fa017ed509a91301f1e9c","title":"菩萨蛮·陇云暗合秋天白","author":"尹鹗 六首","dynasty":"五代","verses":["陇云暗合秋天白，俯窗独坐窥烟陌。","楼际角重吹，黄昏方醉归。","荒唐难共语，明日还应去。","上马出门时，金鞭莫与伊。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-32","tags":[]},{"id":"poem-5010040a63c73ac6988f1a7d","title":"通新代者书偶作","author":"宋伯仁","dynasty":"宋","verses":["庭阴日日杜鹃啼，问我胡为未赋归。","官况苦如梅豆小，人情轻似柳绵飞。","三年独自知操纵，两耳从他说是非。","瓜戍喜催新代者，呆衫应许换征衣。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-1ff1f717-065c-4087-ac40-888464a22eff","tags":[]},{"id":"poem-5015cfa4147fa5e8bf5c486a","title":"浣沙溪・浣溪沙·贪向津亭拥去车","author":"周邦彦","dynasty":"宋","verses":["贪向津亭拥去车。","不辞泥雨溅罗襦。","泪多脂粉了无馀。","酒酽未须令客醉，路长终是少人扶。","早教幽梦到华胥。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-461","tags":[]},{"id":"poem-50235181c8955ae43670a171","title":"浣溪沙·花榭香红烟景迷","author":"毛熙震","dynasty":"五代","verses":["花榭香红烟景迷，满庭芳草绿萋萋，金铺闲掩绣帘低。","紫燕一双娇语碎，翠屏十二晚峰齐，梦魂消散醉空闺。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-34","tags":[]},{"id":"poem-50256ffc6da082aad13312ef","title":"满宫花·花正芳","author":"张泌","dynasty":"五代","verses":["花正芳，楼似绮，寂寞上阳宫里。","钿笼金销睡鸳鸯，帘冷露华珠翠。","娇艳轻盈香雪腻，细雨黄莺双起。","东风惆怅欲清明，公子桥边沉醉。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-45","tags":[]},{"id":"poem-502c910c13f4b47c64dd0709","title":"送袁状元别驾","author":"释居简","dynasty":"宋","verses":["碧苕秋晶晶，君子尚此洁。","渊渊方寸地，上善固一辙。","白苹对红蓼，亦各振清冽。","况复芬陁利，穆若谢炎热。","譬彼寒水玉，温其出冰雪。","其中富涵蓄，其响亦疎越。","有德必有用，无瑕更无缺。","允属清庙器，合在东序设。","君家圣贤学，拟续邹鲁绝。","正音久不作，倩君木为舌。","风月小鸿沟，矧乃龙首杰。","伟兹真富贵，弗与颜原别。","辉辉近芳日，朣朣袖华月。","余光散遐隠，四海俟昭晰。","遗直在山林，放言敢辞拙。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-645835f5-aa22-45b8-ba11-ae8a949655b3","tags":[]},{"id":"poem-502e725e0e7e7afb87521fbc","title":"瑞鹧鸪·洛浦风光烂漫时","author":"李廷忠","dynasty":"宋","verses":["洛浦风光烂漫时。","千金开宴醉为期。","花方著雨犹含笑，蝶不禁寒总是痴。","香腮擎吐浓华艳，不随桃李竞春菲。","东君自有回天力，看把花枝带月归。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-506","tags":[]},{"id":"poem-5032875040a6c604cafe3c96","title":"题池州杜员外弄水新亭","author":"张祜","dynasty":"唐","verses":["广厦光奇辈，恢材卓不群。","夏天平岸水，春雨近山云。","婉衍榱甍揭，端完柱石分。","孤帆惊乍驻，一叶动初闻。","晚槛余清景，凉轩启碧氛。","宾筵习主簿，诗版鲍参军。","露洒新篁滴，风含秀落叶松薰。","何劳思岘岭，虚望汉江滨。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-119155b5-27ae-4d3a-9123-a9697b04bf06","tags":[]},{"id":"poem-503862bad26c6d0e42c3fb08","title":"前腔","author":"施惠《幽闺记》","dynasty":"元","verses":["(旦)依旧珠围翠簇，依旧雕鞍绣毂，列侍妾丫鬟使女，送金杯听歌观舞也。","(小旦)因灾致福，爱惜奴似亲生儿女。","(合前)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3053","tags":[]},{"id":"poem-503eea8df9cb8c61ba012841","title":"江有汜","author":"佚名","dynasty":"先秦","verses":["江有汜，之子归，不我以。不我以，其后也悔。","江有渚，之子归，不我与。不我与，其后也处。","江有沱，之子归，不我过。不我过，其啸也歌。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-21","tags":[]},{"id":"poem-503fb8f4c97b746847a526d3","title":"招魂","author":"宋玉","dynasty":"先秦","verses":["朕幼清以廉洁兮，身服义而未沫。","主此盛德兮，牵于俗而芜秽。","上无所考此盛德兮，长离殃而愁苦。","帝告巫阳曰：“有人在下，我欲辅之。魂魄离散，汝筮予之。”","巫阳对曰：“掌梦！上帝其难从。若必筮予之，恐后之谢，不能复用。”","巫阳焉乃下招曰：魂兮归来！去君之恒干，何为四方些？","舍君之乐处，而离彼不祥些！魂兮归来！东方不可以讬些。","长人千仞，惟魂是索些。","十日代出，流金铄石些。","彼皆习之，魂往必释些。","归来兮！不可以讬些。","魂兮归来！南方不可以止些。","雕题黑齿，得人肉以祀，以其骨为醢些。","蝮蛇蓁蓁，封狐千里些。","雄虺九首，往来倏忽，吞人以益其心些。","归来兮！不可久淫些。","魂兮归来！西方之害，流沙千里些。","旋入雷渊，爢散而不可止些。","幸而得脱，其外旷宇些。","赤蚁若象，玄蜂若壶些。","五谷不生，丛菅是食些。","其土烂人，求水无所得些。","彷徉无所倚，广大无所极些。","归来兮！恐自遗贼些。","魂兮归来！北方不可以止些。","增冰峨峨，飞雪千里些。","归来兮！不可以久些。","魂兮归来！君无上天些。","虎豹九关，啄害下人些。","一夫九首，拔木九千些。","豺狼从目，往来侁侁些。","悬人以嬉，投之深渊些。","致命于帝，然后得瞑些。","归来！往恐危身些。","魂兮归来！君无下此幽都些。","土伯九约，其角觺觺些。","敦脄血拇，逐人伂𬳵𬳵些。","参目虎首，其身若牛些。","此皆甘人，归来！恐自遗灾些。","魂兮归来！入修门些。","工祝招君，背行先些。","秦篝齐缕，郑绵络些。","招具该备，永啸呼些。","魂兮归来！反故居些。","天地四方，多贼奸些。","像设君室，静闲安些。","高堂邃宇，槛层轩些。","层台累榭，临高山些。","网户朱缀，刻方连些。","冬有穾厦，夏室寒些。","川谷径复，流潺湲些。","光风转蕙，泛崇兰些。","经堂入奥，朱尘筵些。","砥室翠翘，挂曲琼些。","翡翠珠被，烂齐光些。","蒻阿拂壁，罗帱张些。","纂组绮缟，结琦璜些。","室中之观，多珍怪些。","兰膏明烛，华容备些。","二八侍宿，射递代些。","九侯淑女，多迅众些。","盛鬋不同制，实满宫些。","容态好比，顺弥代些。","弱颜固植，謇其有意些。","姱容修态，絚洞房些。","蛾眉曼睩，目腾光些。","靡颜腻理，遗视矊些。","离榭修幕，侍君之闲些。","悲帷翠帐，饰高堂些。","红壁沙版，玄玉梁些。","仰观刻桷，画龙蛇些。","坐堂伏槛，临曲池些。","芙蓉始发，杂芰荷些。","紫茎屏风，文缘波些。","文异豹饰，侍陂陁些。","轩辌既低，步骑罗些。","兰薄户树，琼木篱些。","魂兮归来！何远为些？","室家遂宗，食多方些。","稻粢穱麦，挐黄梁些。","大苦醎酸，辛甘行些。","肥牛之腱，臑若芳些。","和酸若苦，陈吴羹些。","胹鳖炮羔，有柘浆些。","鹄酸臇凫，煎鸿鸧些。","露鸡臛蠵，厉而不爽些。","粔籹蜜饵，有𫗠𫗮些。","瑶浆蜜勺，实羽觞些。","挫糟冻饮，酎清凉些。","华酌既陈，有琼浆些。","归来反故室，敬而无妨些。","肴羞未通，女乐罗些。","敶钟按鼓，造新歌些。","《涉江》《采菱》，发《扬荷》些。","美人既醉，朱颜酡些。","嬉光眇视，目曾波些。","被文服纤，丽而不奇些。","长发曼鬋，艳陆离些。","二八齐容，起郑舞些。","衽若交竿，抚案下些。","竽瑟狂会，搷鸣鼓些。","宫庭震惊，发\u003c激楚>些。","吴歈蔡讴，奏大吕些。","士女杂坐，乱而不分些。","放敶组缨，班其相纷些。","郑卫妖玩，来杂陈些。","《激楚》之结，独秀先些。","菎蔽象棋，有六簙些。","分曹并进，遒相迫些。","成枭而牟，呼五白些。","晋制犀比，费白日些。","铿钟摇簴，揳梓瑟些。","娱酒不废，沈日夜些。","兰膏明烛，华灯错些。","结撰至思，兰芳假些。","人有所极，同心赋些。","酎饮尽欢，乐先故些。","魂兮归来！反故居些。","乱曰：献岁发春兮，汨吾南征。","菉苹齐叶兮，白芷生。","路贯庐江兮，左长薄。","倚沼畦瀛兮，遥望博。","青骊结驷兮，齐千乘。","悬火延起兮，玄颜烝。","步及骤处兮，诱骋先。","抑骛若通兮，引车右还。","与王趋梦兮，课后先。","君王亲发兮，惮青兕。","朱明承夜兮，时不可以淹。","皋兰被径兮，斯路渐。","湛湛江水兮，上有枫。","目极千里兮，伤春心。","魂兮归来，哀江南！"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-26","tags":[]},{"id":"poem-504682b4ea934bdee3b68859","title":"新安吏","author":"杜甫","dynasty":"唐","verses":["客行新安道，喧呼闻点兵。","借问新安吏，县小更无丁。","府帖昨夜下，次选中男行。","中男绝短小，何以守王城。","肥男有母送，瘦男独伶俜。","白水暮东流，青山犹哭声。","莫自使眼枯，收汝泪纵横。","眼枯即见骨，天地终无情。","我军取相州，日夕望其平。","岂意贼难料，归军星散营。","就粮近故垒，练卒依旧京。","掘壕不到水，牧马役亦轻。","况乃王师顺，抚养甚分明。","送行勿泣血，仆射如父兄。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-01751db4-8ba6-43f9-a89f-4d96826f5ee1","tags":["忧国忧民","战争"]},{"id":"poem-504b0082e943ad6571828e40","title":"临江仙·渭阙宫城秦树凋","author":"牛希济","dynasty":"五代","verses":["渭阙宫城秦树凋，玉楼独上无聊。","含情不语自吹箫，调情和恨，天路逐风飘。","何事乘龙入忽降，似知深意相招。","三清携手路非遥，世间屏障，彩笔画娇娆。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-35","tags":[]},{"id":"poem-504ddeec7a6b0315d5510a3b","title":"木兰花慢·桂乡云万缕","author":"吕渭老","dynasty":"宋","verses":["桂乡云万缕，更飞雨、洗香车。","念密会经年，银潢浪阻，玉露期赊。","灵星瑞桥对展，散匆匆、喜色满天涯。","回首丁宁晓角，未宜吹动梅花。","家家。","竟赏彩茸，穿桂影、醉流霞。","渐舞袖翻鸾，歌声缀凤，钗影交加。","人间共饶宴乐，算天孙、怎忍遣河斜。","莫惜西楼剪烛，大家同到啼鸦。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-95","tags":[]},{"id":"poem-505528cc71a330ea62c66579","title":"入蓝关","author":"赵嘏","dynasty":"唐","verses":["微烟已辨秦中树，远梦更依江上台。","看落晚花还怅望，鲤鱼时节入关来。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-a0d995b3-6a67-4e5d-8fa4-a84d64e89b18","tags":[]},{"id":"poem-505a58c0863d7c3b6e1fc448","title":"齐天乐·摩挲阅古堂前柳","author":"李寅仲","dynasty":"宋","verses":["摩挲阅古堂前柳，尽是世臣乔木。","故国风流，中兴事业，都写南山修竹。","商颜自绿。","甚当日君王，浩歌鸿鹄。","谁识宫中，有人先定大横卜。","簪貂更鸣佩玉。","退朝归较晚，留传黄屋。","雨露无边，风云在手，宜享长生福。","神京未复。","看先取鸿沟，次封函谷。","岁岁初寒，小桃花下跨青鹿。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-315","tags":[]},{"id":"poem-506fe28aed6c1d9bcea0c354","title":"菩萨蛮·青岩碧洞经朝雨","author":"孙光宪","dynasty":"五代","verses":["青岩碧洞经朝雨，隔花相唤南溪去。","一只木兰船，波平远浸天。","扣舷惊翡翠，嫩玉抬香臂。","红日欲沉西，烟中遥解觽。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-3","tags":[]},{"id":"poem-5071949d8f2961310a8e02bf","title":"送令狐尚书赴东都留守","author":"张籍","dynasty":"唐","verses":["朝廷重寄在关东，共说从前选上公。","勋业新城大梁镇，恩荣更守洛阳宫。","行香暂出天桥上，巡礼常过禁殿中。","每领群臣拜章庆，半开门仗日曈曈。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-c90e225a-331a-4f78-9e14-f930489e2cff","tags":[]},{"id":"poem-5072b184b3b6f5077820b55f","title":"水壶子","author":"贯休","dynasty":"唐","verses":["良匠曾陶莹，多居笔砚中。","一从亲几案，常恐近儿童。","卓立澄心久，提携注意通。","不应嫌器小，还有济人功。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-1dc06baa-9966-4a88-9a9b-fa9ed08e5d4a","tags":[]},{"id":"poem-5078b2f582fcc52a8afba42e","title":"度南涧","author":"蔡襄","dynasty":"唐","verses":["隠隠飞桥隔野烟，石矶西畔问渔船。","桃花尽日随流水，洞在清溪何处边。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-e72db286-3b6a-425b-ad02-75248ea5a790","tags":["描写水","写景","抒情","唐诗三百首","七言绝句","写水"]},{"id":"poem-508c0a9c2bce87c01c614d59","title":"临江仙·忆昔西池池上饮","author":"晁冲之","dynasty":"宋","verses":["忆昔西池池上饮，年年多少欢娱。","别来不寄一行书。","寻常相见了，犹道不如初。","安稳锦屏今夜梦，月明好度江湖。","相思休问定何如。","情知春去后，管得落花无。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-246","tags":["宋词三百首"]},{"id":"poem-5092ad51b3665859f687d670","title":"女冠子·含娇含笑","author":"温庭筠","dynasty":"唐","verses":["含娇含笑，宿翠残红窈窕。","鬓如蝉，寒玉簪秋水，轻纱卷碧烟。","雪胸鸾镜里，琪树凤楼前。","寄语青娥伴，早求仙。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-47","tags":[]},{"id":"poem-50a46571b45760d02e9309ad","title":"郊庙歌辞 仪坤庙乐章 金奏","author":"不详","dynasty":"唐","verses":["阴灵曜祉，轩曜降精。","祥符淑气，庆集柔明。","瑶俎既列，雕桐发声。","徽猷永远，比德皇英。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-fe67914f-1ea9-4c19-96cd-fd01efec5274","tags":[]},{"id":"poem-50ae0f7a2ee6a393687f1300","title":"献衷心·绣鸳鸯帐暖","author":"顾敻","dynasty":"五代","verses":["绣鸳鸯帐暖，画孔雀欹。","人悄悄，月明时，想昔年欢笑，恨今日分离。","银背，铜漏永，阻佳期。","小炉烟细，虚阁帘垂。","几多心事，暗地思惟。","被娇娥牵役，魂梦如痴。","金闺里，山枕上，始应知。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-17","tags":[]},{"id":"poem-50b020177d5759f073db73e9","title":"病起书蕉叶  其二","author":"释居简","dynasty":"宋","verses":["摇青已见及时荣，猎猎翩翩衬短楹。","似我不才非世用，对伊侧枕听秋声。","影铺缺甃侵苔绿，丛倚疎櫺蔽月明。","脆弱不胜连夜雨，亟凭幽讨饯余清。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-a8aa802c-c903-4b5a-aaca-a42fa8449bd6","tags":[]},{"id":"poem-50b4099f999002bb161a2ca3","title":"张次东中奉挽词三首  其一","author":"李纲","dynasty":"宋","verses":["贾父褰帷日，于公驷马门。","十年持使节，两郡拥朱轓。","无复功名会，空余气槩存。","凄凉九原路，楚些与招魂。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-05ce676a-486b-4a48-b6b4-0f55b7dc1809","tags":[]},{"id":"poem-50b4e72550f64c4e65ce474d","title":"二子乘舟","author":"佚名","dynasty":"先秦","verses":["二子乘舟，泛泛其景。愿言思子，中心养养！","二子乘舟，泛泛其逝。愿言思子，不瑕有害？"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-43","tags":[]},{"id":"poem-50b6e04847e13607ff0266cd","title":"句","author":"王湾","dynasty":"唐","verses":["月华照杵空随妾，风响传砧不到君。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-6d77d022-7335-45c9-aa82-0e1725555536","tags":[]},{"id":"poem-50b8ed7ef06d4a95c2be20e9","title":"酬郭先辈","author":"徐铉","dynasty":"宋","verses":["太原郭夫子，行高文炳蔚。","弱龄负世誉，一举游月窟。","仙籍第三人，时人故称屈。","昔余吏西省，倾盖名籍籍。","及我窜群舒，向风心鬰鬰。","归来暮江上，云雾一披拂。","雷雨不下施，犹作池中物。","念君介然气，感时思奋发。","示我数篇文，与古争驰突。","彩缛粲英华，理深刮肌骨。","古诗尤精奥，史论皆宏拔。","举此措诸民，何忧民不活。","吁嗟吾道薄，与世长迂阔。","顾我徒有心，数奇身正绌。","论兵属少年，经国须儒术。","夫子无自轻，苍生正愁疾。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-c55f549d-4887-442d-83a8-ae464761b8bc","tags":[]},{"id":"poem-50c0a86cdf17997d57d79078","title":"送裴宣城上元所居","author":"李嘉祐","dynasty":"唐","verses":["水流过海稀，尔去换春衣。","泪向槟榔尽，身随鸿雁归。","草思晴后发，花怨雨中飞。","想到金陵渚，酣歌对落晖。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-c8a0aa65-3552-4460-9a5a-08eecec348a7","tags":[]},{"id":"poem-50c7c4d3fc0c91a282bebffe","title":"良田无晚岁","author":"张佐","dynasty":"唐","verses":["人功虽未及，地力信非常。","不任耕耘早，偏宜黍稷良。","无年皆有获，后种亦先芳。","膴膴盈千亩，青青保万箱。","何须祭田祖，讵要察农祥。","况是春三月，和风日又长。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-1c2a1bfc-9b0c-48ef-a5f1-c6a028bc0837","tags":[]},{"id":"poem-50d72966437d68a7f1cab3a8","title":"兔爰","author":"佚名","dynasty":"先秦","verses":["有兔爰爰，雉离于罗。我生之初，尚无为；我生之后，逢此百罹。尚寐无吪。","有兔爰爰，雉离于罦。我生之初，尚无造；我生之后，逢此百忧。尚寐无觉。","有兔爰爰，雉离于罿。我生之初，尚无庸；我生之后，逢此百凶。尚寐无聪。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-69","tags":[]},{"id":"poem-50db633cf1132276d7098358","title":"西江月·花额上堆翠葆","author":"谢逸","dynasty":"宋","verses":["花额上堆翠葆，远山横处星眸。","绛宫深锁暮云浮。","月破黄昏时候。","谁谓霞衣玉简，便孤彩凤秦楼。","桃源不禁昔人游。","曾是刘郎邂逅。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-603","tags":[]},{"id":"poem-50e2091cf6b9d16ccc359889","title":"下第日书情寄上叔父","author":"司空曙","dynasty":"唐","verses":["微才空觉滞京师，末学曾为叔父知。","雪里题诗偏见赏，林间饮酒独令随。","游客尽伤春色老，贫居还惜暮阴移。","欲归江海寻山去，愿报何人得桂枝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-0d8d840d-1f94-44da-9b52-18a01cf8ed82","tags":[]},{"id":"poem-50e22e6ccbd19ca25812a218","title":"葛藟","author":"佚名","dynasty":"先秦","verses":["绵绵葛藟，在河之浒。终远兄弟，谓他人父。谓他人父，亦莫我顾！","绵绵葛爰，在河之藟。终远兄弟，谓他人母。谓他人母，亦莫我有！","绵绵葛藟，在河之漘。终远兄弟，谓他人昆。谓他人昆，亦莫我闻！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-70","tags":[]},{"id":"poem-50e40671b21daec3d0c85be1","title":"访沈舍人不遇","author":"赵嘏","dynasty":"唐","verses":["溪翁强访紫微郎，晓鼓声中满鬓霜。","知在禁闱人不见，好风飘下九天香。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-8a3438e4-946a-47f7-8457-9a80f0e4c3b8","tags":[]},{"id":"poem-50e48e1890313f668a3cce90","title":"瀑布联句","author":"宣宗皇帝","dynasty":"唐","verses":["千岩万壑不辞劳，远看方知出处高。","溪涧岂能留得住，终归大海作波涛。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-79b4be2b-65d5-412f-82ed-48d8b804fabc","tags":[]},{"id":"poem-50e67bb6ad36488fd8c72bb3","title":"横吹曲辞 洛阳道","author":"郑渥","dynasty":"唐","verses":["客亭门外路东西，多少喧腾事不齐。","杨柳惹鞭公子醉，纻麻掩泪鲁人迷。","通宵尘土飞山月，是处经营夹御堤。","顷刻知音几存殁，半回依约认轮蹄。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-9997e88a-f75c-47ec-a336-359bb426fcf4","tags":[]},{"id":"poem-50e684dba26e3dc65c143095","title":"从元太守夏䜩西楼","author":"王建","dynasty":"唐","verses":["六月晨亦热，卑居多烦昏。","五马游西城，几杖随朱轮。","西楼临方塘，嘉木当华轩。","凫鹥满中流，有酒复盈尊。","山东地无山，平视大海垠。","高风凉气来，灏景沈清源。","青衿俨坐傍，礼容益敦敦。","愿为颜氏徒，歌咏夫子门。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-44108987-73c2-4661-a258-cab7d617838b","tags":[]},{"id":"poem-50ebe1d4e81dfd95e07d7ade","title":"孝顺歌","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["孙员外，家富足，他们有的是金共玉。","你一心嫁寒儒，缘何弃撇汝？［旦］容奴禀覆，未必儿夫将奴辜负。","那一个横死贼徒，忒兀自生嫉妒？［净］这纸书你重看取，明写着赘相府。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8197","tags":[]},{"id":"poem-50f215e1bf07d3fffe0caabf","title":"送王端赴朝","author":"李嘉祐","dynasty":"唐","verses":["君承明主意，日日上丹墀。","东阁论兵后，南宫草奏期。","人稀傍河处，槐暗入关时。","独遣吴州客，平陵结梦思。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-d93b38b6-87b1-4440-9a3e-ef787ece0177","tags":[]},{"id":"poem-50f6627714369d668ad8d43a","title":"山有扶苏","author":"佚名","dynasty":"先秦","verses":["山有扶苏，隰有荷华。不见子都，乃见狂且。","山有乔松，隰有游龙，不见子充，乃见狡童。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-83","tags":[]},{"id":"poem-50fd2f7d3f198a996fbb8d7b","title":"南乡子·十月小春天","author":"李石","dynasty":"宋","verses":["十月小春天。","红叶红花半雨烟。","点滴红酥真耐冷，争先。","夺取梅魂斗雪妍。","坐待晓莺迁。","织女机头蜀锦川。","枝上绿毛幺凤子，飞仙。","乞与双双作被眠。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-272","tags":[]},{"id":"poem-5106f769c4e3d403c65e2ac1","title":"甘草子·秋尽","author":"柳永","dynasty":"宋","verses":["秋尽。","叶翦红绡，砌菊遗金粉。","雁字一行来，还有边庭信。","飘散露华清风紧。","动翠幕、晓寒犹嫩。","中酒残妆慵整顿。","聚两眉离恨。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-58","tags":[]},{"id":"poem-5116e0ee6d120cf3ab3cb4c5","title":"玉楼春·拂水双飞来去燕","author":"顾敻","dynasty":"五代","verses":["拂水双飞来去燕，曲槛小屏山六扇。","春愁凝思结眉心，绿绮懒调红锦荐。","话别情多声欲战，玉箸痕留红粉面。","镇长独立到黄昏，却怕良宵频梦见。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-49","tags":[]},{"id":"poem-514235c1f1f1d7e461631063","title":"和秉国芙蓉五章  其五","author":"司马光","dynasty":"宋","verses":["但见涉江求水际，岂知胜木采霜中。","微红未肯全衰歇，正似酡颜鸖髪翁。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-ccb7ffe8-b414-43b8-bf2e-fb84ca8d8772","tags":[]},{"id":"poem-5152c174258952a4584281b9","title":"减字木兰花·凭高一览","author":"倪偁","dynasty":"宋","verses":["凭高一览。","紫翠相围光照眼。","下瞰平湖。","鹭立鸥飞意自如。","天清境胜。","云澹烟横鱼动镜。","不是公诗。","谁写新亭一段奇。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-463","tags":[]},{"id":"poem-5154640f33443e1041e93310","title":"岁晚烹试小春建茶","author":"张栻","dynasty":"宋","verses":["阳月藏春妙莫窥，灵芽粟粒露全机。","煮泉独啜寒窗夜，已觉东风天际归。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-e4779b88-6c84-4f41-87d7-5dd0edfe76a7","tags":[]},{"id":"poem-515f73be8b25c8de392ededd","title":"凤时春","author":"萧德祥《小孙屠》","dynasty":"元","verses":["得失荣枯在命，夫妻事岂非天为。","我的孩儿今成夫妇，论此因缘，事皆前定。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8598","tags":[]},{"id":"poem-5164d1fc337f3ba0b5aada46","title":"临江仙·雪壁歌词题尚湿","author":"葛胜仲","dynasty":"宋","verses":["雪壁歌词题尚湿，春风又见轻红。","一枝斜插映头峰。","不辞连夜赏，银烛透纱笼。","白发欺人今老矣，尊前羞见繁秾。","清香尤嫪虎溪风。","海棠须避席，佳种谩蚕丛。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-34","tags":[]},{"id":"poem-516b0dcf0b5cef7a6f01df66","title":"观猎","author":"薛逢","dynasty":"唐","verses":["马缩寒毛鹰落臕，角弓初暖箭新调。","平原踏尽无禽出，竟日翻身望碧霄。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-ba6b993b-d939-4323-8fde-af6076038270","tags":[]},{"id":"poem-516f203f6fe21026990dacd1","title":"颂古三十一首  其二三","author":"释安永","dynasty":"宋","verses":["问处分明答处亲，纵横有路惯反身。","相如夺得连城璧，秦主安然致太平。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-84c2aa26-479f-4b40-8777-f566ba29e558","tags":[]},{"id":"poem-517bc35f153c71a5d34e83fc","title":"捕守宫","author":"赵文","dynasty":"宋","verses":["向来上阳人，尽属沙叱利。","长门不用守，蜥蜴草间戏。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-51f7e427-979e-4ad5-87d5-50dde3f69eb7","tags":[]},{"id":"poem-517f184e38a3c2fbc8acb637","title":"乌程水楼留别","author":"皇甫曾","dynasty":"唐","verses":["悠悠千里去，惜此一尊同。","客散高楼上，帆飞细雨中。","山程随远水，楚思在青枫。","共说前期易，沧波处处同。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-189ab60e-c415-4aa2-b883-e6a899426407","tags":[]},{"id":"poem-517f9e839684090be9ee73dc","title":"水龙吟·闹花深处层楼","author":"陈亮","dynasty":"宋","verses":["闹花深处层楼，画帘半卷东风软。","春归翠陌，平莎茸嫩，垂杨金浅。","迟日催花，淡云阁雨，轻寒轻暖。","恨芳菲世界，游人未赏，都付与、莺和燕。","寂寞凭高念远。","向南楼、一声归雁。","金钗斗草，青丝勒马，风流云散。","罗绶分香，翠绡封泪，几多幽怨。","正销魂，又是疏烟淡月，子规声断。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-118","tags":["宋词三百首"]},{"id":"poem-518f150a38b84ebcfc742430","title":"未展芭蕉","author":"钱珝","dynasty":"唐","verses":["冷烛无烟绿蜡干，芳心犹卷怯春寒。","一缄书箚藏何事，会被东风暗拆看。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-26b06f1c-4632-42a2-9658-31b725d90e59","tags":[]},{"id":"poem-51976765d4993012bccbd334","title":"祀风师乐章 迎神","author":"包佶","dynasty":"唐","verses":["太皞御气，句芒肇功。","苍龙青旗，爰候祥风。","律以和应，神以感通。","鼎俎修蚃，时惟礼崇。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-28b2515e-49c3-49f9-8702-d7b63a8136f4","tags":[]},{"id":"poem-51ad92ae9f8cfe16f94e2082","title":"何人斯","author":"佚名","dynasty":"先秦","verses":["彼何人斯？其心孔艰。胡逝我梁，不入我门？伊谁云从？维暴之云。","二人从行，谁为此祸？胡逝我梁，不入唁我？始者不如今，云不我可。","彼何人斯？胡逝我陈？我闻其声，不见其身。不愧于人？不畏于天？","彼何人斯？其为飘风。胡不自北？胡不自南？胡逝我梁？𫄨搅我心。","尔之安行，亦不遑舍。尔之亟行，遑脂尔车。一者之来，云何其盱。","尔还而入，我心易也。还而不入，否难知也。一者之来，俾我𫄨也。","伯氏吹埙，仲氏吹篪。及尔如贯，谅不我郑出此三物，以诅尔斯。","为鬼为蜮，则不可得。有腼面目，视人罔极。作此好歌，以极反侧。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-198","tags":[]},{"id":"poem-51bbdb5dac8d9f0e35edb60b","title":"宿淮浦忆司空文明","author":"李端","dynasty":"唐","verses":["愁心一倍长离忧，夜思千重恋旧游。","秦地故人成远梦，楚天凉雨在孤舟。","诸溪近海潮皆应，独树边淮叶尽流。","别恨转深何处写，前程唯有一登楼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-e7b59ce3-5d91-4ee2-b8ef-32416721d445","tags":[]},{"id":"poem-51bd03f4c1b786b709c01493","title":"送郑孝廉淮西觐省","author":"皎然","dynasty":"唐","verses":["离袂翠华满，晨羞欲早行。","春风生楚树，晓角发隋城。","野霭湿衣彩，江鸿增客情。","征途不用戒，坐见白波清。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-3571ccea-faa3-42ec-bb60-33cbb4d2f112","tags":[]},{"id":"poem-51bdaa05c08caedc3bc0afd7","title":"茅斋","author":"纳兰性德","dynasty":"清","verses":["闲亭照白日，一室罗古今。","偶焉此栖迟，抱膝悠然吟。","吟罢有余适，散瞩复披襟。","时开玉怀卷，或弹珠柱琴。","檐树吐新花，枝头语珍禽。","花发饶冶色，禽鸣多姣音。","色冶眩春目，音姣伤春心。","夕阳下虞渊，寂莫还空林。","清光复相照，片月西山岭。","东园桃李姿，是妾嫁君时。","燕婉为夫妇，相爱不相离。","良人忽远征，妾独守空帏。","忧来恒自叹，冀死魂追随。","又念妾死时，谁制万里衣。","幸有双鲤鱼，拟为寄君辞。","终日不成章，含泪自封题。","君若得鲤鱼，剖鱼开素书。","但看行中字，一一与泪俱。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-217","tags":[]},{"id":"poem-51bf0c684b30221ea5c28a31","title":"寄菖蒲","author":"张籍","dynasty":"唐","verses":["石上生菖蒲，一寸十二节。","仙人劝我食，令我头青面如雪。","逢人寄君一绛囊，书中不得传此方。","君能来作栖霞侣，与君同入丹玄乡。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-08a57734-3ccb-4ba5-bfe5-a33ac611c1af","tags":[]},{"id":"poem-51cb3c1f88fa2e23aaf17b0f","title":"题令狐处士谿居","author":"项斯","dynasty":"唐","verses":["白发已过半，无心离此溪。","病尝山药徧，贫起草堂低。","为月窗从破，因诗壁重泥。","近来常夜坐，寂莫与僧齐。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-3945113d-2603-4c26-8739-050a676f2868","tags":[]},{"id":"poem-51e62caac9ab1e71e6cb4e1b","title":"调笑・调笑令·渔父饮时花作荫","author":"洪适","dynasty":"宋","verses":["渔父饮时花作荫。","羹鱼煮蟹无它品。","世代太平除酒禁。","渔父饮。","绿蓑藉地胜如锦。","渔父醉时收钓饵。","鱼梁晒翅闲乌鬼。","白浪撼船眠不起。","渔父醉。","滩声无尽清双耳。","渔父醒时清夜永。","澄澜过尽征鸿影。","略略风来敧舴艋。","渔父醒。","月高露下衣裳冷。","渔父笑时莺未老。","提鱼入市归来早。","一叶浮家生计了。","渔父笑。","笑中起舞《渔家傲》。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-667","tags":[]},{"id":"poem-51e956011081ddf3ca4b0829","title":"古瑟怨","author":"李益","dynasty":"唐","verses":["破瑟悲秋已减弦，湘灵沈怨不知年。","感君拂拭遗音在，更奏新声明月天。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-699800d5-6ce3-4f34-8f68-78b6c32f7202","tags":[]},{"id":"poem-51f204e1a066182303aaff17","title":"子规","author":"来鹄","dynasty":"唐","verses":["雨恨花愁同此冤，啼时闻处正春繁。","千声万血谁哀尔，争得如花笑不言。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-3b7c7212-79b7-4d89-bfb6-763add437897","tags":[]},{"id":"poem-51f316125ed2407082e49c2f","title":"游鴈荡","author":"钱元㺷","dynasty":"唐","verses":["东风驿路马蹄香，晓起行春到夕阳。","三月莺啼花柳寺，几家人住水云乡。","名山不用问樵字，清世何须忧庙廊。","且脱[纶巾]（轮轩）（从《南雁荡山志》改）随洞客，紫箫吹月夜天凉。","（见民国十四年符璋等纂《平阳县志》卷九五。","题下原注：「旧志。","」）（按：元㺷，《平阳县志》作「元球」。","《十国春秋》卷八三本传注云：「按《晋高祖实录》、《十国纪年》作元球、元珦以罪诛，今从《吴越备史》、《九国志》作元㺷。","」今从其说。","张靖龙云：见周喟《南雁荡山志》卷七引郑思恭《崇祯南雁山志》。","又见《乾隆平阳县志》卷二，题作《游雁荡山诗》，纶巾作轮轩。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-ac4ce0c8-25fb-4bb8-9c76-df32a93e9800","tags":[]},{"id":"poem-51f4f19acef8cd67b61ea4e6","title":"金钱花","author":"来鹄","dynasty":"唐","verses":["也无棱郭也无神，露洗还同铸出新。","青帝若教花里用，牡丹应是得钱人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-0b823010-6edb-4594-8db7-98b47827647c","tags":[]},{"id":"poem-51f775f8d5fc6153ec912a01","title":"又泛西溪诗十首  其五","author":"刘跂","dynasty":"宋","verses":["天生桥畔水交流，夹岸花飞逐客舟。","时听山禽歌一曲，何须吹笛舞凉州。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-48f4e3ee-fb09-4c9b-ab9c-469d6713ab58","tags":[]},{"id":"poem-51fbaca299bb68b2088a1d89","title":"德升尚书再用前韵见示五绝 窗下独酌","author":"綦崇礼","dynasty":"宋","verses":["忘忧有妙理，细与曲生论。","相携醉乡去，醒见月当门。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-f00d67e2-8f6a-4c14-acc5-3d78faa30799","tags":[]},{"id":"poem-520ecf7a2a822ad24a64116d","title":"燕台二首 二","author":"聂夷中","dynasty":"唐","verses":["燕台高百尺，燕灭台亦平。","一种是亡国，犹得礼贤名。","何似章华畔，空余禾黍生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-afc32e5a-8518-496b-a4a5-b4c995251763","tags":[]},{"id":"poem-52109afef1fa4c623f6b1630","title":"感皇恩·风雨揽元宵","author":"史浩","dynasty":"宋","verses":["风雨揽元宵，收灯方了。","深院红莲尚围绕。","德星同聚，更有祥光临照。","始知真洞府，春长好。","应是化工，偏怜衰老。","剩把青藜作荣耀。","正须沈醉，拚却玉山频倒。","寄声更漏子，休催晓。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-50","tags":[]},{"id":"poem-5210c02deab0ae5f1b9f05b4","title":"河传·红杏","author":"张泌","dynasty":"五代","verses":["红杏，交枝相映，密密蒙蒙。","一庭浓艳倚东风，香融，透帘栊。","斜阳似共春光语，蝶争舞，更引流莺妒。","魂销千片玉樽前，神仙，瑶池醉暮天。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-40","tags":[]},{"id":"poem-52183c28eec249b8f751f985","title":"歇拍","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["不告父母，怎谐匹偶？臣又听得，家乡里，遭水旱，遇荒饥。","多想臣亲，必做沟渠之鬼，末可知。","怎不教臣，悲伤汨垂？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5026","tags":[]},{"id":"poem-5219583198069d9622c43a27","title":"洞仙歌·江陵种橘","author":"晁补之","dynasty":"宋","verses":["江陵种橘，尚比封侯贵。","何况江涛转千里。","带天香，含洞乳，宜入春盘，红荔子，驰驿风流仅比。","齿疏潘令老，怯咀冰霜，十颗金苞谩分遗。","记觞前、须细认，别有馀甘，从此去，枉却栽桃种李。","想相如酒渴对文君，迥不是人间，等闲风味。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-289","tags":[]},{"id":"poem-521f2ef18aca84232cd51874","title":"酒泉子·月落星沉","author":"韦庄","dynasty":"五代","verses":["月落星沉，楼上美人春睡。","绿云倾，金枕腻，画屏深。","子规啼破相思梦，曙色东方才动。","柳烟轻，花露重，思难任。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-23","tags":[]},{"id":"poem-521fa888fa374f4fda789842","title":"送李中丞杨判官","author":"李嘉祐","dynasty":"唐","verses":["射策名先著，论兵气自雄。","能全季布诺，不道鲁连功。","流水蒹葭外，诸山睥睨中。","别君秋日晚，回首夕阳空。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-50b98014-0f20-4554-b959-8c8929b28582","tags":[]},{"id":"poem-5222aab2b4a888f89eaf6bd3","title":"菩萨蛮·隔帘微雨双飞燕","author":"李珣","dynasty":"五代","verses":["隔帘微雨双飞燕，砌花零落红深浅。","捻得宝筝凋，心随征棹遥。","楚天云外路，动便经年去。","香断画屏深，旧欢何处寻。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-45","tags":[]},{"id":"poem-522c6c155321d0cfc10b070c","title":"哭秘书包大监","author":"孟郊","dynasty":"唐","verses":["哲人卧病日，贱子泣玉年。","常恐宝镜破，明月难再圆。","文字未改素，声容忽归玄。","始知知音稀，千载一绝弦。","旧馆有遗琴，清风那复传。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-983d12ef-7554-4fcc-8bdb-3a5f18e57932","tags":[]},{"id":"poem-522fc9fa43cca0dd7d4faa44","title":"舟中苦热遣怀奉呈[阳]中丞通简台省诸公","author":"杜甫","dynasty":"唐","verses":["媿为湖外客，看此戎马乱。","中夜混黎甿，脱身亦奔窜。","平生方寸心，反掌帐下难。","呜呼杀贤良，不叱白刃散。","吾非丈夫特，没齿埋冰炭。","耻以风病辞，胡然泊湘岸。","入舟虽苦热，垢腻可溉灌。","痛彼道边人，形骸改昏旦。","中丞连帅职，封内权得按。","身当问罪先，县实诸侯半。","士卒既辑睦，启行促精悍。","似闻上游兵，稍逼长沙馆。","邻好彼克修，天机自明断。","南图卷云水，北拱戴霄汉。","美名光史臣，长策何壮观。","驱驰数公子，咸愿同伐叛。","声节衰有余，夫何激衰懦。","偏裨表三上，卤莽同一贯。","始谋谁其间，回首增愤惋。","宗英李端公，守职甚昭焕。","变通迫胁地，谋画焉得算。","王室不肯微，凶徒略无惮。","此流须卒斩，神器资强干。","扣寂豁烦襟，皇天照嗟叹。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-d95fc5a3-4109-4871-8615-5d71f248eace","tags":[]},{"id":"poem-523420ab69d6ec5f732a8e11","title":"四皓图","author":"贯休","dynasty":"唐","verses":["何人图四皓，如语话唠唠。","双鬓雪相似，是谁年最高。","溪苔连豹褥，仙酒污云袍。","想得忘秦日，伊余亦合逃。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-091dfdbf-c8d1-4d28-9da0-f956f5583bbf","tags":[]},{"id":"poem-5236789f210300290323faaf","title":"僻居秋思寄友人","author":"伍乔","dynasty":"宋","verses":["门巷秋归更寂寥，雨余闲砌委兰苗。","梦回月夜虫吟壁，病起茅斋药满瓢。","泽国旧游关远思，竹林前会负佳招。","身名未立犹辛苦，何许流年晚鬓凋。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-f2bd645b-940c-41d1-a5a0-de0c495c6d7c","tags":[]},{"id":"poem-5238eb776d1f36831d43ce3b","title":"寄江州萧给事","author":"徐铉","dynasty":"宋","verses":["夕郎忧国不忧身，今向天涯作逐臣。","魂梦暗驰龙阙曙，啸吟闲绕虎谿春。","朝车载酒过山寺，谏纸题诗寄野人。","惆怅懦夫何足道，自离群后已同尘。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-b766d7a8-383e-4b18-b46c-d2e3c49eb8c2","tags":[]},{"id":"poem-523dcc8342e3c1479be5712b","title":"鹧鸪天·雁贴寒云次第飞","author":"纳兰性德","dynasty":"清","verses":["雁帖寒云次第飞，向南犹自怨归迟。","谁能瘦马关山道，又到西风扑鬓时。","人杳杳，思依依，更无芳树有乌啼。","凭将扫黛窗前月，持向今宵照别离。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-112","tags":[]},{"id":"poem-5240bd638631d84920458a8d","title":"适庄兄游山","author":"王柏","dynasty":"宋","verses":["谁阁重阴一日晴，清游应是惬高情。","遥知雨后山光好，但想云边屐齿清。","素壁虽曾题旧字，沈疴不许插新盟。","因知关吏留鱼钥，谩遣奚奴候晚程。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-c5a1663d-0759-4511-83ca-e90667e6fc98","tags":[]},{"id":"poem-524818b51855c027801ca615","title":"浣溪沙·半踏长裾宛约行","author":"孙光宪","dynasty":"五代","verses":["半踏长裾宛约行，晚帘疏处见分明，此时堪恨昧平生。","早是消魂残烛影，更愁闻着品弦声，杳无消息若为情。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-41","tags":[]},{"id":"poem-524ab4cad3a04b96c6425f8f","title":"阁前双槿","author":"杨凌","dynasty":"唐","verses":["群玉开双槿，丹荣对绛纱。","含烟疑出火，隔雨怪舒霞。","向晚争辞蘂，迎朝鬬发花。","非关后桃李，为欲继年华。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-b1ea1885-1c8e-4c3f-abf4-829c989b8058","tags":[]},{"id":"poem-525960722146414c6e376470","title":"凤凰台上忆吹箫·千里相思","author":"晁补之","dynasty":"宋","verses":["千里相思，况无百里，何妨暮往朝还。","又正是、梅初淡伫，禽未绵蛮。","陌上相逢缓辔，风细细、云日斑斑。","新晴好，得意未妨，行尽青山。","应携后房小妓，来为我，盈盈对舞花间。","便拼了、松醪翠满，蜜炬红残。","谁信轻鞍射虎，清世里、曾有人闲。","都休说，帘外夜久春寒。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-128","tags":[]},{"id":"poem-525c624754c3796f52cc51c8","title":"南吕/一枝花","author":"杨景贤","dynasty":"元","verses":["大宛国天产才，渥洼水龙媒种。","带轻云一块雪，走落日四蹄风。","长尾银鬃，驮双将无嫌重，出群驽立大功。","胜普贤白象身高，赛师利青狮性勇！。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-10114","tags":[]},{"id":"poem-525d6e797a314ed4e8a9a63d","title":"邹律","author":"苏拯","dynasty":"唐","verses":["邹律暖燕谷，青史徒编录。","人心不变迁，空吹闲草木。","世患有三惑，尔律莫能抑。","边苦有长征，尔律莫能息。","斯术未济时，斯律亦何益。","争如至公一开口，吹起贤良霸邦国。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-9e1ca461-7267-41ca-b2ef-d8bbe5df888c","tags":[]},{"id":"poem-52629664dc4c91486b452761","title":"报文成","author":"张𬸦","dynasty":"唐","verses":["他道愁胜死，儿言死胜愁。","日夜悬心忆，知隔几年秋。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-1b7fce5f-35ff-4f2c-af35-c310917eb151","tags":[]},{"id":"poem-5265279f65c8b7092f452a20","title":"古镜歌三首 二","author":"泰钦","dynasty":"唐","verses":["谁云古镜无样度，古人出入何门户？","门户君看不见时，即此为君全显露。","全显露（《大正藏》本无此三字），与汝一生终保护。","若遇知音请益来，逢人不得轻分付。","但任作见面，不须生怕怖，看取当时演若多，直至如今成错悮。","如今不省影分明，还是当时同一顾。","同一顾，苦苦苦！。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-166d7f05-0e01-481e-88b0-187a3b4e6937","tags":[]},{"id":"poem-5266b0d191a7da96556ea9b7","title":"次程帅和陶诗韵","author":"陈造","dynasty":"宋","verses":["昔吾窃科第，正自学力勤。","虽从士夫后，禄已不及亲。","痛感韦经传，敢忘择孟邻。","念汝知策厉，灯夜仍鸡晨。","立志忌作辍，惜阴计寸分。","盍抽胸次陈，驱为笔底春。","解颜献新得，眩眼释峤云。","鉏头足膏腴，天人巧相因。","奉亲有如此，况予耐贱贫。","谁今子不如，俪美须前人。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-9188cecd-9790-43b9-9cf9-cd0bbd6e7634","tags":[]},{"id":"poem-526e13c235c4595619ad2ff9","title":"生查子·含羞整翠鬟","author":"欧阳修","dynasty":"宋","verses":["含羞整翠鬟，得意频相顾。","雁柱十三弦，一一春莺语。","娇云容易飞，梦断知何处。","深院锁黄昏，阵阵芭蕉雨。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-625","tags":[]},{"id":"poem-526ea08dad69b651c6af8443","title":"答林昌宗诗筌韵","author":"刘翼","dynasty":"宋","verses":["经锄小暇弄诗筌，老去仍知默是禅。","沧海移舟尽琴趣，虽然终不似无弦。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-919eac34-6d78-45d5-94d8-1bace9ca0f9d","tags":[]},{"id":"poem-526ea289db3700cbbe91023f","title":"川鲍老","author":"无名氏《张协状元》","dynasty":"元","verses":["君在两山，两山成出字。","(末白)两个山是出字。","(丑连唱)遇一人假虎衣。","白虎算来，只在西方旺，西方却是川地。","君出去向北尽得，不免有些，跌扑脓血疾。","千里外豹变，一时掀焰，归来贺喜。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2463","tags":[]},{"id":"poem-5275aea13dbb95184517978c","title":"梦还京·夜来匆匆饮散","author":"柳永","dynasty":"宋","verses":["夜来匆匆饮散，敧枕背灯睡。","酒力全轻，醉魂易醒，风揭帘栊，梦断披衣重起。","悄无寐。","追悔当初，绣阁话别太容易。","日许时、犹阻归计。","甚况味。","旅馆虚度残岁。","想娇媚。","那里独守鸳帏静，永漏迢迢，也应暗同此意。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-70","tags":[]},{"id":"poem-5278806714324386e6949faf","title":"步出夏门行 土不同","author":"曹操","dynasty":"汉","verses":["乡土不同，河朔隆冬。","流澌浮漂，舟船行难。","锥不入地，蘴藾深奥。","水竭不流，冰坚可蹈。","士隐者贫，勇侠轻非。","心常叹怨，戚戚多悲。","幸甚至哉！歌以咏志。"],"enabled":true,"collection":"曹操诗集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/曹操诗集/caocao.json#record-23","tags":[]},{"id":"poem-528ff1ba37654303e442f493","title":"酬秘书王丞见寄","author":"张籍","dynasty":"唐","verses":["相看头白来城阙，却忆漳溪旧往还。","今体诗中偏出格，常参官里每同班。","街西借宅多临水，马上逢人亦说山。","芸阁水曹虽最冷，与君长喜得身闲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-9d8abe6e-b38b-4777-9219-083db49583cb","tags":[]},{"id":"poem-5291446877a394f07b01016d","title":"小戎","author":"佚名","dynasty":"先秦","verses":["小戎俴收，五楘梁辀。游环胁驱，阴靷鋈续。文茵畅毂，驾我骐馵。","言念君子，温其如玉。在其板屋，乱我心曲。","四牡孔阜，六辔在手。骐骝是中，䯄骊是骖。龙盾之合，鋈以觼軜。","言念君子，温其在邑。方何为期？胡然我念之！","俴驷孔群，厹矛鋈𬭚。蒙伐有苑，虎韔镂膺。交韔二弓，竹闭绲縢。","言念君子，载寝载兴。厌厌良人，秩秩德音。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-127","tags":[]},{"id":"poem-529624e6545eec356d636259","title":"赴举别所知","author":"李山甫","dynasty":"唐","verses":["腰劒囊书出户迟，壮心奇命两相疑。","麻衣尽举一双手，桂树只生三两枝。","黄祖不怜鹦鹉客，志公偏赏麒麟儿。","叔牙忧我应相痛，回首天涯寄所思。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-e50c8203-889f-4852-883e-eceb9fd2486c","tags":[]},{"id":"poem-529e696388ffdc490a62347e","title":"题城南书院三十四咏  其二八","author":"张栻","dynasty":"宋","verses":["朝阳初上藕花香，下马虚亭一味凉。","山鸟自呼鱼自乐，谁云身世可相忘。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-f4d4e440-de2b-48f8-a91e-55fa187b1bfb","tags":[]},{"id":"poem-52a2b272251979bd176a15a2","title":"南乡子·洞口谁家","author":"欧阳炯","dynasty":"五代","verses":["洞口谁家，木兰船系木兰花。","红袖女郎相引去，游南浦，笑倚春风相对语。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-3","tags":[]},{"id":"poem-52a8ea5712068c577b2b8e54","title":"咏史诗 南阳","author":"胡曾","dynasty":"唐","verses":["世乱英雄百战余，孔明方此乐耕锄。","蜀王不自垂三顾，争得先生出旧庐。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-bfda82d8-3c7d-4443-b1be-3959502a3c96","tags":[]},{"id":"poem-52a9451b6e9e5a69b0ec2140","title":"怀香炉峰道人","author":"贯休","dynasty":"唐","verses":["常思峰顶叟，石窟土为床。","日日先见日，烟霞多异香。","冥心同槁木，扫雪带微阳。","终必相寻去，斯人不可忘。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-6f578b08-7dd6-414e-bcc7-23acbed69df6","tags":[]},{"id":"poem-52b013da11505d49afd39a9f","title":"送张环摄御史监南选","author":"孙逖","dynasty":"唐","verses":["汉使得张纲，威名摄远方。","恩沾柱下史，荣比选曹郎。","江带黔中阔，山连峡水长。","莫愁炎暑地，秋至有严霜。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-e731f0bb-24f2-42fb-ac7a-a79bbe04858a","tags":[]},{"id":"poem-52b0cd1a07184b86ae6d33a3","title":"寄许下前管记王侍御","author":"谭用之","dynasty":"宋","verses":["昔年南去得娱宾，顿逊杯前共好春。","蚁泛羽觞蛮酒腻，凤衔瑶句蜀牋新。","花怜游骑红随辔，草恋征车碧遶轮。","别后青青郑南陌，不知风月属何人。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-a9e4be45-154e-447f-af63-1ff134006aae","tags":[]},{"id":"poem-52b963e0c099e427e5a0d348","title":"立秋","author":"刘言史","dynasty":"唐","verses":["兹晨戒流火，商飇早已惊。","云天收夏色，木叶动秋声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-0be6139d-9f86-4c80-8689-babed4019d9f","tags":[]},{"id":"poem-52bfb5bbbdde727b3ceaf36f","title":"六九","author":"王梵志","dynasty":"唐","verses":["蒙人惠一恩，终身酬不极。","若济桒（郑本作桑。","）下饥，扶论可惜力。","（「论」，伯三七一六卷作「轮」。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-32acdafd-8557-41b2-a060-aceeb93bf5c4","tags":[]},{"id":"poem-52c52850e924f7f2442c454f","title":"盛京","author":"纳兰性德","dynasty":"清","verses":["拔地蛟龙宅，当关虎豹城。","山连长白秀，江入混同清。","庙社灵风肃，豪强右族更。","明明开创业，休拟作陪京。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-228","tags":[]},{"id":"poem-52c67d74524ae8e44a617f89","title":"送崔五太守","author":"王维","dynasty":"唐","verses":["长安厩吏来到门，朱文露网动行轩。","黄花县西九折坂，玉树宫南五丈原。","襃斜谷中不容幰，唯有白云当露冕。","子午山里杜鹃啼，嘉陵水头行客饭。","劒门忽断蜀川开，万井双流满眼来。","雾中远树刀州出，天际澄江巴字回。","使君年纪三十余，少年白皙专城居。","欲持画省郎官笔，回与临邛父老书。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-7f232909-cb6c-4da8-afde-d3ff9fcea204","tags":[]},{"id":"poem-52c765f5e0f15c13bf7225c0","title":"相思","author":"王维","dynasty":"唐","verses":["红豆生南国，秋来发故枝。","愿君多采撷，此物最相思。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-8baa7c35-9afb-40bf-b5e4-41d9895e2710","tags":["唐诗三百首","思念","咏物","抒情","咏物诗","五言绝句"]},{"id":"poem-52d18193b0c4d2cdd7bf6f54","title":"金缕歌・贺新郎·乔木生云气","author":"吴文英","dynasty":"宋","verses":["乔木生云气。","访中兴、英雄陈迹，暗追前事。","战舰东风悭借便，梦断神州故里。","旋小筑、吴宫闲地。","华表月明归夜鹤，叹当时、花竹今如此。","枝上露，溅清泪。","遨头小簇行春队。","步苍苔、寻幽别坞，问梅开未。","重唱梅边吸度曲，催发寒梢冻蕊。","此心与、东君同意。","后不如今非昔，两无言、相对沧浪水。","怀此恨，寄残醉。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-87","tags":["宋词三百首"]},{"id":"poem-52d1ed985ee8a9d135679362","title":"谢程帅袁制使  其五","author":"陈造","dynasty":"宋","verses":["江左风流人，安石颇巨擘。","丝竹不去耳，用逃忧患域。","陶琴不须弦，我辈所矜式。","设逢东山翁，兕觥与浮白。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-340273df-4658-441f-8cea-ff7c3f231f1a","tags":[]},{"id":"poem-52d23bbe3d820efb0207773f","title":"伴云来・天香·烟络横林","author":"贺铸","dynasty":"宋","verses":["烟络横林，山沈远照，逦迤黄昏钟鼓。","烛映帘栊，蛩催机杼，共苦清秋风露。","不眠思妇，齐应和、几声砧杵。","惊动天涯倦宦，岁华行暮。","当年酒狂自负。","谓东君、已春相付。","流浪征骖北道，客墙南浦。","幽恨无人晤语。","赖明月曾知旧游处。","好伴云来，还将梦去。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-76","tags":["宋词三百首"]},{"id":"poem-52d38f50a77d1ed4eeab1bf2","title":"蝶恋花·北固山前波浪远","author":"仲殊","dynasty":"宋","verses":["北固山前波浪远。","铁瓮城头，画角残声短。","促酒溅金催小宴。","灯摇蜡焰香风软。","落日烟霞晴满眼。","欲仗丹青，巧笔彤牙管。","解写伊川山色浅。","谁能画得江天晚。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-888","tags":[]},{"id":"poem-52d4da21615ed8ab15acee7b","title":"女冠子·步虚坛上","author":"鹿虔扆","dynasty":"五代","verses":["步虚坛上，绛节霓旌相向，引真仙。","玉佩摇蟾影，金炉袅麝烟。","露浓霜简湿，风紧羽衣偏。","欲留难得住，却归天。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-16","tags":[]},{"id":"poem-52db7ffaca9023367a628e19","title":"生查子·关山魂梦长","author":"杜安世","dynasty":"宋","verses":["关山魂梦长，寒雁音书少。","两鬓可怜青，只为相思老。","归傍碧纱窗，说向人人道。","真个别离难，不似相逢好。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-917","tags":[]},{"id":"poem-52db9f8bec2e27911ec47611","title":"玉蝴蝶·目断江南千里","author":"晁冲之","dynasty":"宋","verses":["目断江南千里，灞桥一望，烟水微茫。","尽锁重门，人去暗度流光。","雨轻轻，梨花院落，风淡淡、杨柳池塘。","恨偏长。","佩沈湘浦，云散高唐。","清狂。","重来一梦，手搓梅子，煮酒初尝。","寂寞经春，小桥依旧燕飞忙。","玉钩栏、凭多渐暖，金缕枕、别久犹香。","最难忘。","看花南陌，待月西厢。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-659","tags":[]},{"id":"poem-52e213b5f114cd1f94240004","title":"三段子","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["(小生)翁今几儿？(外)念箕裘无人可倚。","(小生)族分几枝？(外)念宗支无人可悲。","(小生)你既然只身一己，如何不上倚贤婿？况是他殷勤想伊。","(小生)叫左右，与我打点马船人夫，送钱相公到吉安府去。","(外)如此多感多感！。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8305","tags":[]},{"id":"poem-52e303c4802980fab3d01e17","title":"鹧鸪天·帝乙何年骑玉龙","author":"王以宁","dynasty":"宋","verses":["帝乙何年骑玉龙。","武夷仙伯笑相从。","长庚瑞应游仙梦，碧藕花开解愠风。","歌既醉，乐元丰。","明良相悦寿无穷。","野人更有深深祝，笑指三台十八公。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-69","tags":[]},{"id":"poem-52e7c8563069d2fec4623cc7","title":"洛中士君子多以平泉见呼愧获方外之名因以此诗为报奉寄刘宾客","author":"李德裕","dynasty":"唐","verses":["非高柳下逸，自爱竹林闲。","才异居东里，愚因在北山。","径荒寒未扫，门设昼长关。","不及鸱夷子，悠悠烟水间。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-3282311c-bea6-4f03-83ba-e4e0dd5457ca","tags":[]},{"id":"poem-52f98098861dad1424fe83fa","title":"歌","author":"元寂","dynasty":"唐","verses":["酒秃酒秃，何荣何辱。","但见衣冠成古丘，不见江河变陵谷。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-3c0acdd4-79dd-4f19-93ab-513eb1147024","tags":[]},{"id":"poem-53117b2589b8f74f2dc1341f","title":"如梦令·深苑重调弦管","author":"毛滂","dynasty":"宋","verses":["深苑重调弦管。","不觉银台烛短。","相对有金波，天畔杯中都满。","人远。","人远。","醉倚阑干玉冷。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-856","tags":[]},{"id":"poem-5313d9dab08dead69669253d","title":"耒阳杜工部祠堂","author":"孟宾于","dynasty":"宋","verses":["南游何感思，更甚叶缤纷。","一夜耒江雨，百年工部文。","青山当日见，白酒至今闻。","惟有为诗者，经过时吊君。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-c73b151d-2012-41aa-bcd9-6705ff87d52d","tags":[]},{"id":"poem-531c04762db5545fff1c5b37","title":"闺情（为落殊蕃陈上相知人） 闺情 一","author":"高适","dynasty":"唐","verses":["相随万里泣胡风，疋偶将期一世终。","早知中路生离别，悔不深怜沙碛中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-4413e116-18be-4c17-b9c1-eb8891418c6f","tags":[]},{"id":"poem-53211529c9ac23a9643e6382","title":"水调歌头·元日至人日","author":"范成大","dynasty":"宋","verses":["元日至人日，未有不阴时。","新年叶气，无处人物不熙熙。","万岁声从天下，一札恩随春到，光采动天鸡。","寿域遍寰海，直过雪山西。","忆曾预，宣玉册，捧金卮。","如今万里，魂梦空绕五云飞。","想见大庭宫馆，重起三山楼观，双指赭黄衣。","此会古无有，何止古来稀。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-258","tags":[]},{"id":"poem-53365921580e855b2fd5df23","title":"浣溪沙·荷芰风轻帘幕香","author":"顾敻","dynasty":"五代","verses":["荷芰风轻帘幕香，绣衣㶉𫛶泳回塘，小屏闲掩旧潇湘。","恨入空帷鸾影独，泪凝双脸渚莲光，薄情年少悔思量。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-2","tags":[]},{"id":"poem-53378018c2ba7180c4623e13","title":"鹧鸪天·金节平分院落凉","author":"谢逸","dynasty":"宋","verses":["金节平分院落凉。","黄昏帘幕卷西厢。","冰轮碾碎粼粼碧，玉斧修成练练光。","低照户，巧侵床。","锦袍起舞谪仙狂。","鹊飞影里觥筹乱，桂子风前笑语香。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-636","tags":[]},{"id":"poem-533a1d001a977a5d77cd3d87","title":"叶梦授送家园梅花且以绝句十五章见示次其韵  其七","author":"李纲","dynasty":"宋","verses":["超然标格冠群芳，妙质天教彻骨香。","烂熳开时何足道，最怜新蘂半涂黄。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-f497b379-6740-40e3-ac2e-4e54c42ac993","tags":[]},{"id":"poem-533f18866a3e2fdeff39c58c","title":"南歌子·萧寺疏锺断","author":"蔡伸","dynasty":"宋","verses":["萧寺疏锺断，虚堂夜气清。","凉蟾偏向小明窗。","露井碧梧寒叶、颤秋声。","幽恨人谁问，孤衾泪独横。","此时风月此时情。","拟倩蓝桥归梦、见云英。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-971","tags":[]},{"id":"poem-5340014f40fe40aa73a4f7a3","title":"与月船周君话别  其一","author":"王同祖","dynasty":"宋","verses":["明日须知子遂行，一灯对语过三更。","离魂已逐歌声断，清梦空随夜雨生。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-a2d2ac7f-6195-4cd3-b959-a7a8f0b50a35","tags":[]},{"id":"poem-5345f49792d22398e41a9b0a","title":"踏莎行·倚柳题笺","author":"纳兰性德","dynasty":"清","verses":["倚柳题笺，当花侧帽，赏心应比驱驰好。","错教双鬓受东风，看吹绿影成丝早。","金殿寒鸦，玉阶春草，就中冷暖和谁道。","小楼明月镇长闲，人生何事缁尘老。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-127","tags":[]},{"id":"poem-534e77d111d7b7d320432673","title":"采桑子·城南城北看桃李","author":"黄庭坚","dynasty":"宋","verses":["城南城北看桃李，依倚年华。","杨柳藏鸦。","又是无言飐落花。","春风一面长含笑，偷顾羞遮。","分付谁家。","把酒花前试问他。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-789","tags":[]},{"id":"poem-5354597d5fc6569045502b44","title":"次韵和丹阳裴如晦学士寄示与蔡子直陈述古唱酬五篇  其一","author":"苏颂","dynasty":"宋","verses":["登瀛忝继唐词客，补郡仍陪汉望郎。","政事将何攀邵杜，声名空贵蹑王杨。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-3259bb1a-d4d5-49d7-9b17-f0449a9ea3d7","tags":[]},{"id":"poem-535b827cbec4c1db8979c10b","title":"菩萨蛮·小庭花落无人归","author":"孙光宪","dynasty":"五代","verses":["小庭花落无人归，疏香满地东风老。","春晚信沉沉，天涯何处寻。","晓堂屏六扇，眉共湘山远。","怎奈别离心，近来尤不禁。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-2","tags":[]},{"id":"poem-535d6f526860b8abb69391bb","title":"六叹 二","author":"李涉","dynasty":"唐","verses":["深院梧桐夹金井，上有辘轳青丝索。","美人清昼汲寒泉，寒泉欲上银缾落。","迢迢碧甃千余尺，竟日倚阑空叹息。","惆怅不来照明镜，却掩洞房抱寂寂。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-3724d7b6-b2a4-4325-9adb-ab513afbed22","tags":[]},{"id":"poem-5364318ce60a71f9c2583497","title":"郊庙歌辞 周郊祀乐章 禋顺乐","author":"不详","dynasty":"唐","verses":["黄彝将献，特牲预迎。","既修昭事，潜达明诚。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-0ff009da-1154-46ae-bc65-af8c9372f08d","tags":[]},{"id":"poem-5381f3faf942b45737ceae99","title":"龙池春草","author":"李洞","dynasty":"唐","verses":["龙池清禁里，芳草傍池春。","旋长方遮岸，全生不染尘。","和风轻动色，湛露静流津。","浅得承天步，深疑遶御轮。","鱼寻倒影没，花带湿光新。","肯学长河畔，绵绵思远人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-a48e607f-f9e9-414c-b9f8-ef456d4a0fa6","tags":[]},{"id":"poem-53823a817943c0cd67877fd8","title":"赠薛勋下第","author":"赵嘏","dynasty":"唐","verses":["一掷虽然未得卢，惊人不用绕床呼。","牢之坐被青云逼，祗问君能酷似无。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-b10ee1ae-744a-4af9-933a-05ca3cd49c06","tags":[]},{"id":"poem-5384fe045d9db48c8e86efda","title":"丰","author":"佚名","dynasty":"先秦","verses":["子之丰兮，俟我乎巷兮，悔予不送兮。","子之昌兮，俟我乎堂兮，悔予不将兮。","衣锦褧衣，裳锦褧裳。叔兮伯兮，驾予与行。","裳锦褧裳，衣锦褧衣。叔兮伯兮，驾予与归。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-87","tags":[]},{"id":"poem-5386b644568fec821ed065d7","title":"秋日即目","author":"太宗皇帝","dynasty":"唐","verses":["爽气浮丹阙，秋光澹紫宫。","衣碎荷疎影，花明菊点丛。","袍轻低草露，盖侧舞松风。","散岫飘云叶，迷路飞烟鸿。","砌冷兰凋佩，闺寒树陨桐。","别鹤栖琴里，离猿啼峡中。","落野飞星箭，弦虚半月弓。","芳菲夕雾起，暮色满房栊。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-a609556d-746c-4703-97a2-0aac7168fce7","tags":[]},{"id":"poem-539f847096b24d1d5c2c2b47","title":"奉和御制茱萸","author":"徐铉","dynasty":"宋","verses":["台畔西风御果新，芳香精彩丽萧辰。","柔条细叶妆治好，紫蔕红芳点缀匀。","几朵得陪天上宴，千株长作洞中春。","今朝圣藻偏流咏，黄菊无由更敢邻。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-9667c285-4024-4ba1-a5d3-759a5b81a653","tags":[]},{"id":"poem-539fd9f1782061186ca714ce","title":"引军旗","author":"徐田臣《杀狗记》","dynasty":"元","verses":["听拜禀：令弟不仁，赎毒药害你身。","兄弟见了痛伤情，哥哥自宜思忖。","(生)舍弟是读书人至诚，无此事不须忧闷。","(合)思之，祸福生死皆由命，果然半点不由人。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1711","tags":[]},{"id":"poem-53a981254b02032610c78dbd","title":"颂古三十一首  其一六","author":"释玿","dynasty":"宋","verses":["明日大悲院里斋，铁围山岳尽冲开。","猪头象鼻，乌觜鱼腮。","石人抚掌呵呵笑，寒山拾得在天台。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-37610d77-d4b1-47c7-9120-2dd3e57b735a","tags":[]},{"id":"poem-53ae4da49eeef685b5211fe9","title":"甘州令·冻云深","author":"柳永","dynasty":"宋","verses":["冻云深，淑气浅，寒欺绿野。","轻雪伴、早梅飘谢。","艳阳天，正明媚，却成潇洒。","玉人歌，画楼酒，对此景、骤增高价。","卖花巷陌，放灯台榭。","好时节、怎生轻舍。","赖和风，荡霁蔼，廓清良夜。","玉尘铺，桂华满，素光里、更堪游冶。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-215","tags":[]},{"id":"poem-53b56d579e0dc4dc3ebab002","title":"送濮阳录事赴忠州","author":"李端","dynasty":"唐","verses":["成名不遂双旌远，主印还为一郡雄。","赤叶黄花随野岸，青山白水映江枫。","巴人夜语孤舟里，越鸟春啼万壑中。","闻说古书多未校，肯令才子久西东。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-898151bf-b3b7-4387-b41c-f56da1575e2e","tags":[]},{"id":"poem-53b7228c32254ea3bf8885c9","title":"题横水驿双峰院松","author":"赵嘏","dynasty":"唐","verses":["故园溪上雪中别，野馆门前云外逢。","白发渐多何事苦，清阴长在好相容。","迎风几拂朝天骑，带月犹含度岭钟。","更忆葛洪丹井畔，数株临水欲成龙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-afade0d6-6e8e-4b1e-854e-a3fb8705aa20","tags":[]},{"id":"poem-53c09c85bc810b66cc68416e","title":"柳枝·瑟瑟罗裙金缕腰","author":"和凝","dynasty":"五代","verses":["瑟瑟罗裙金缕腰，黛眉偎破未重描。","醉来咬损新花子，拽住仙郎尽放娇。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-30","tags":[]},{"id":"poem-53c64746d77cb687c87c21d8","title":"南望楼","author":"卢僎","dynasty":"唐","verses":["去国三巴远，登楼万里春。","伤心江上客，不是故乡人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-4cdad806-1bfb-41de-8adf-a7f5cef159b2","tags":[]},{"id":"poem-53c95bb27530d4adf18f3bfe","title":"送张乔下第归宣州","author":"李洞","dynasty":"唐","verses":["诗道世难通，归宁楚浪中。","早程残岳月，夜泊隔淮钟。","一镜随双鬓，全家老半峰。","无成来往过，折尽谢亭松。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-7d00b4df-f560-4cb3-92e9-eb2282038793","tags":[]},{"id":"poem-53ccac9969453863e23afa87","title":"江行无题一百首 六十一","author":"钱珝","dynasty":"唐","verses":["堤坏漏江水，地坳成野塘。","晚荷人不折，留取作秋香。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-c5f4e9c6-31c4-48a6-8979-28fcd85053d3","tags":[]},{"id":"poem-53cd8a713c0ab2b99b4bd3db","title":"渔家傲引・渔家傲·七月凛秋飞叶响","author":"洪适","dynasty":"宋","verses":["七月凛秋飞叶响。","长吟杳杳澄江上。","秃尾槎头添一网。","丝自纺。","新炊菰饭更相饷。","渡口青烟藏叠嶂。","岸旁红蓼翻轻浪。","㶉𫛶沈浮双漾漾。","闻鸣桨。","高飞拍拍穿林莽。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-661","tags":[]},{"id":"poem-53d66125abb0e94704b6de2b","title":"题柳郎中故居","author":"李德裕","dynasty":"唐","verses":["下马荒堦日欲曛，潺潺石溜静中闻。","鸟啼花发人声绝，寂寞山窗掩白云。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-137687e4-9cf2-4f1b-a168-214b6a568f8a","tags":[]},{"id":"poem-53dceefd28857392b37e0413","title":"赠施都正三首  其一","author":"陈造","dynasty":"宋","verses":["严严神仙居，不受世尘涴。","栖身白玉壶，眼净讵容唾。","主人敬爱客，马秣仆不饿。","洗心炉薰前，容了旧经课。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-52d47aeb-e046-4d70-8240-4d674cbb95c7","tags":[]},{"id":"poem-53e3f71d22ab2d6e8f4de34a","title":"项别驾讣临","author":"释居简","dynasty":"宋","verses":["清约筋骸别，云泥俗肺肠。","酌贪廉不污，鉴正丑难藏。","贵药无钱买，沉疴有死偿。","若为千驷马，得似蕨薇香。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-c4a6f4f8-4552-4c5e-859e-a08750c310ba","tags":[]},{"id":"poem-53e6306e22976923e30191a0","title":"苏东坡挽诗五首  其一","author":"米芾","dynasty":"宋","verses":["方瞳正碧貌如圭，六月相逢万里归。","口不谈时经噩梦，心常怀蜀俟秋衣。","可怜众热偏能舍，自是登真限莫违。","书到乡人望还舍，晋陵玄鹤已孤飞。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-1d3dfed1-13d1-407d-869e-210f576d9db0","tags":[]},{"id":"poem-53e981c9fb0557933482a397","title":"听夜泉","author":"刘得仁","dynasty":"唐","verses":["静里层层石，潺湲到鹤林。","流回出几洞，源远历千岑。","寒助空山月，清兼此夜心。","幽人听达曙，相和藓床吟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-1e51c2e4-da56-4b03-a51c-efd01ac12d4e","tags":[]},{"id":"poem-53ea9ba11d65531df3718ee3","title":"夏日与綦毋居士昱上人纳凉","author":"皎然","dynasty":"唐","verses":["为依炉峰住，境胜增道情。","凉日暑不变，空门风自清。","坐援香实近，转爱绿芜生。","宗炳青霞士，如何知我名。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-1e620d71-ca49-4c19-bb6d-1c8666de7ad5","tags":[]},{"id":"poem-53eb050f6d9d74607ed0a489","title":"挽郑十一府君并夫人","author":"华镇","dynasty":"宋","verses":["君子言无玷，夫人德有邻。","丝桐人世远，窀穸陇头新。","粧合闲明镜，吟窗积暗尘。","西风原上路，鸣铎为悲辛。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-825b7fa0-976f-41da-9ebe-2e7b75419109","tags":[]},{"id":"poem-53fce8fd611b45b9e9256497","title":"春秋战国门 荆轲","author":"周昙","dynasty":"唐","verses":["反刃相酬是匹夫，安知突骑驾群胡。","有心为报怀权畧，可在于期与地图。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-51dd0d1a-01d4-434b-8257-a15d7f9c218b","tags":[]},{"id":"poem-5405f76e947cb3fd1525f307","title":"同前","author":"无名氏《张协状元》","dynasty":"元","verses":["莫将去，念身上寒，况兼又无旅店。","时运蹇，望君今，善眼相看！。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2486","tags":[]},{"id":"poem-54157fea8c0314a1a240cb8d","title":"美人对镜歌","author":"许玠","dynasty":"宋","verses":["天上雄鸡啼一声，人间万鸡相应鸣。","美人红酣尚未醒，锁掣金匙鹦鹉惊。","鹦鹉从来巧言语，声聒锦帏残梦起。","猛揎罗袖窝绿云，步逼妆台趁梳洗。","玉奁脱覆光烁人，洞房环曲惊晓春。","不是清空月飞入，如何中有姮娥身。","轩辕百炼今湮灭，扬州青铜却奇绝。","人非照镜镜照人，镜亦分明为人说。","媸妍一镜固两般，狐妇怀奸心胆寒。","闺中少女色庄丽，眉颊不妨终日看。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-03e0b6f2-bb28-473d-a5ba-7273a5f87b3d","tags":[]},{"id":"poem-54178f30e27cdf7eccbbf1de","title":"陈正字山居","author":"李咸用","dynasty":"唐","verses":["一叶闲飞斜照里，江南仲蔚在蓬蒿。","天衢云险驽骀蹇，月桂风和梦想劳。","遶枕泉声秋雨细，对门山色古屏高。","此中即是神仙地，引手何妨一钓鼇。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-eb17d113-a2f4-47aa-bdbd-4b4ff1cadfb6","tags":[]},{"id":"poem-542189a8ade25a8d737608d3","title":"东瓯令","author":"施惠《幽闺记》","dynasty":"元","verses":["(旦上)我那娘！心如醉，泪交流。","去远家尊绝信久，途中母子生离别。","这苦如何受？一重愁翻做两重愁，是我命合休。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2934","tags":[]},{"id":"poem-5422668ef86daa616e63bf6b","title":"酬别襄阳诗僧少微","author":"皎然","dynasty":"唐","verses":["证心何有梦，示说梦归频。","文字赍秦本，诗骚学楚人。","兰开衣上色，柳向手中春。","别后须相见，浮云是我身。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-1a759495-20b9-4da4-8905-bd32aa2be24c","tags":[]},{"id":"poem-54255be8cef8abeef4db26e5","title":"酒泉子·花映柳条","author":"温庭筠","dynasty":"唐","verses":["花映柳条，闲向绿萍池上。","凭栏干，窥细浪，雨萧萧。","近来音信两疏索，洞房空寂寞。","掩银屏，垂翠箔，度春宵。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-22","tags":[]},{"id":"poem-54366cb8cf845211990dc5d6","title":"木兰花・玉楼春·插花劝酒盐桥馆","author":"张先","dynasty":"宋","verses":["插花劝酒盐桥馆。","召节促行龙阙远。","吴船渐起晚潮生，蛮榼未空寒日短。","庆门奕世隆宸眷。","归到月陂梅已绽。","有情愿寄向南枝，图得洛阳春色看。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-366","tags":[]},{"id":"poem-5458fe9c851b260c01746ce7","title":"挂真儿","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(生上)积善之家庆有余，传留下万卷诗书。","性禀刚贞，胸怀仁义，更喜门庭豪贵。","两字功名志未酬，藏珠韫玉且优游。","家传阀阅经多载，世代簪缨知几秋。","天谄诈，有刚柔，果然名字播皇州。","家中财宝如山积，库内钱财似水流。","卑人姓孙，名华，排行第一，祖贯东京人氏。","曾攻诗史，未遂风云。","喜得家道丰盈，尽可优游岁月。","荆妻杨氏，妇道颇娴。","侍女迎春，家规能守。","有个同胞兄弟。","唤做孙荣，从小是卑人抚养成人，今经一十八岁，未曾婚匹。","一应家事，俱是卑人总理。","他只在学馆攻书，见成安享。","这也罢了。","奈他性多执拗，才欠圆通。","胸中之学，或者有余；户外之事，全然未晓。","每每触忤卑人，屡加训责，他从无怨恨之心，奈绝无顺从之美。","正所谓\"江山易改，禀性难移\"。","近来卑人结识得两个好友，一个是柳龙卿，一个是胡子传。","此二人不但诗礼之儒，颇饶豪侠之气；又且知机识变，博学多能。","物情市价，无所不通；官讼家常，何事不晓。","与卑人相爱相亲，如同手足。","卑人意欲结义他为兄弟。","一来家中百事，商量有靠；二来要他教导孙荣，使他通些世务。","昨日已曾对柳、胡二友说过了。","也要兄弟孙荣在内，不免与兄弟通知。","兄弟孙荣那里？(小生扮孙荣上)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1690","tags":[]},{"id":"poem-545ffea835b13bab2d3b6a13","title":"时迈","author":"佚名","dynasty":"先秦","verses":["时迈其邦，昊天其子之，实右序有周。薄言震之，莫不震叠。怀柔百神，及河乔岳，允王维后。","明昭有周，式序在位。载戢干戈，载橐弓矢。我求懿德，四于时夏，允王保之。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-272","tags":[]},{"id":"poem-546ea6b7a10a42d2329fd327","title":"去涟水","author":"米芾","dynasty":"宋","verses":["长日开闲境，春风美鼻雷。","黄䌷依旧暖，牙鼓莫相催。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-833d48e3-2a12-4b48-8d88-d466737a6231","tags":[]},{"id":"poem-546ec7a955586f60f2ab2311","title":"出蓝田关寄董使君","author":"陆畅","dynasty":"唐","verses":["万里烟萝锦帐间，云迎水送度蓝关。","七盘九折难行处，尽是龚黄界外山。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-51e76f1b-82f4-452e-aaa1-d2845d291d3a","tags":[]},{"id":"poem-54769c267c522830197823a9","title":"今夕行","author":"杜甫","dynasty":"唐","verses":["今夕何夕岁云徂，更长烛明不可孤。","咸阳客舍一事无，相与博塞为欢娱。","冯陵大叫呼五白，袒跣不肯成枭卢。","英雄有时亦如此，邂逅岂即非良图。","君莫笑刘毅从来布衣愿，家无儋石输百万。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-092c35a3-eaf8-4078-86e6-fb338c21f085","tags":[]},{"id":"poem-547992be4db28432f08e8c05","title":"卧病别郑锡","author":"李端","dynasty":"唐","verses":["病来喜无事，多卧竹林间。","此日一相见，明朝还掩关。","幽人爱芳草，志士惜颓颜。","岁[晏]不我弃，期君在故山。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-d166bb61-1756-49af-8967-29ae96ddf592","tags":[]},{"id":"poem-5479fe0edfcd40282691aba8","title":"寓言","author":"皎然","dynasty":"唐","verses":["人生百年我过半，天生才定不可换。","东海钓鼇鼇不食，南山坐石石欲烂。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-7ff78979-1ada-457d-906b-d0aa39930a5d","tags":[]},{"id":"poem-547f75532fb86f48cfa04bee","title":"二十六日作真率会伯康与君从七十八歳安之七十七歳正叔七十四歳不疑七十三歳叔达七十歳光六十五歳合五百一十五歳口号成诗用安之前韵  其一","author":"司马光","dynasty":"宋","verses":["七人五百有余歳，同醉花前今古稀。","走马斗鸡非我事，纻衣丝髪且相晖。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-82cc586f-e736-43a1-8e56-e136fe96903f","tags":[]},{"id":"poem-5483cba37b7a5af7c09ac225","title":"粉蝶儿","author":"萧德祥《小孙屠》","dynasty":"元","verses":["生长开封，诗书尽皆历遍，奈功名五行薄浅。","论荣华,随分有，称吾心愿。","且开怀，共诗朋酒侣欢宴。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8563","tags":[]},{"id":"poem-5489bf8a7430d9e1ba100f63","title":"仙人塘","author":"陈岩","dynasty":"宋","verses":["陂塘一曲水泓澄，山簇瑶台十二层。","剩脉余膏流不尽，芝田蕙圃岁常登。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-231ea2d3-7f29-4c6a-8983-cbf1b5cf2445","tags":[]},{"id":"poem-549106146d00e15037d6f196","title":"老夫采玉歌","author":"李贺","dynasty":"唐","verses":["采玉采玉须水碧，琢作步摇徒好色。","老夫饥寒龙为愁，蓝溪水气无清白。","夜雨冈头食蓁子，杜鹃口血老夫泪。","蓝溪之水厌生人，身死千年恨溪水。","斜山柏风雨如啸，泉脚挂绳青褭褭。","村寒白屋念娇婴，古台石磴悬肠草。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-c8ca253f-7981-4bcc-a6dc-b7444401d39f","tags":[]},{"id":"poem-5495193b5770303987c08292","title":"春秋战国门 郄成子","author":"周昙","dynasty":"唐","verses":["陈乐无懽璧在隅，宰臣怀智有微谟。","苟非成子当明哲，谁是仁人可托孤。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-e063be80-e19f-42fb-abab-0a8c082a1ff3","tags":[]},{"id":"poem-54a20142f2d40ee04f2267a2","title":"冬至","author":"杜甫","dynasty":"唐","verses":["天时人事日相催，冬至阳生春又来。","刺绣五纹添弱线，吹葭六管动飞灰。","岸容待腊将舒柳，山意冲寒欲放梅。","云物不殊乡国异，教儿且覆掌中杯。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-冬至","tags":[]},{"id":"poem-54b0d5bf2eabc9572d01b6f1","title":"喜迁莺·金门晓","author":"薛昭蕴","dynasty":"五代","verses":["金门晓，玉京春，骏马骤轻尘。","桦烟深处白衫新，认得化龙身。","九陌喧，千户启，满袖桂香风细。","杏园欢宴曲江滨，自此占芳辰。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-35","tags":[]},{"id":"poem-54b6547258aae280eac59e1c","title":"深上人见访忆李端","author":"司空曙","dynasty":"唐","verses":["雁稀秋色尽，落日对寒山。","避事多称疾，留僧独闭关。","心归尘俗外，道胜有无间。","仍忆东林友，相期久不还。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-99b28edd-1f27-415b-993f-f7ca05f18279","tags":[]},{"id":"poem-54bbf917280090517d092a1b","title":"奉和圣制重阳赐会聊示所怀","author":"李泌","dynasty":"唐","verses":["大唐造昌运，品物荷时成。","乘秋逢令节，锡宴欢群情。","俯临秦山川，高会汉公卿。","未追赤松子，且泛黄菊英。","赓歌圣人作，海内同休明。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-9ee1065e-adba-4eda-bec9-2b69c95bab2c","tags":["抒怀","重阳节"]},{"id":"poem-54c246e854ed4b96f0d8a45d","title":"挂真儿","author":"萧德祥《小孙屠》","dynasty":"元","verses":["东岳灵祠几程路，还心愿只得前去。","只虑家中，无人看觑，叫出孩儿说与。","(生上唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8628","tags":[]},{"id":"poem-54c7201e78f7cc63da032556","title":"西江月·此道至神至圣","author":"张伯端","dynasty":"宋","verses":["此道至神至圣，忧君分薄难消。","调和铅汞不终朝。","早睹玄珠形兆。","志士若能修炼，何妨在市居朝。","工夫容易药非遥。","说破人须失笑。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-970","tags":[]},{"id":"poem-54d056c9a3dfbaa6aaf2dff4","title":"渔父","author":"释居简","dynasty":"宋","verses":["谋生与俗违，一叶浪中蜚。","水易分团月，云难隠少微。","雁沙眠晚照，鸥渚櫂晴霏。","见说蓬莱浅，寻津问钓矶。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-a0694a3e-9573-433a-b78f-d0cd81051259","tags":[]},{"id":"poem-54d85a760e7f508e048a62a8","title":"师亲写版牌云 一","author":"义存","dynasty":"唐","verses":["妄身临镜照影，影与妄身不殊。","若欲去影留身，不知身影常虚。","身影从来不异，不得一有一无。","若拟憎凡爱圣，生死海里常浮。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-aba26bd0-0c7a-4cf0-a77f-4fc940c7900b","tags":[]},{"id":"poem-54e32c66399c283a4252cde6","title":"春秋战国门 再吟","author":"周昙","dynasty":"唐","verses":["走敌存亡义有余，全由雄勇与英谟。","但如公子能交结，朱亥侯嬴何代无。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-8a764c6c-1b5f-4b5f-b482-82a41e3d54ae","tags":[]},{"id":"poem-54e39da5387e8d1c1910fff0","title":"送孙德谕罢官往黔州","author":"苗发","dynasty":"唐","verses":["中岁分符典石城，两朝趋陛谒承明。","阙下昨承归老疏，天南今切去乡情。","亲知握手三秋别，几杖扶身万里行。","伯道暮年无嗣子，欲将家事托门生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-d5a61d84-8246-462a-beae-fea8dbc3c0df","tags":[]},{"id":"poem-54e4d9af7fb7c147b76081fb","title":"金人捧露盘·净业寺观莲有怀荪友","author":"纳兰性德","dynasty":"清","verses":["藕风轻，莲露冷，断虹收，正红窗、初上帘钩。","田田翠盖，趁斜阳鱼浪香浮。","此时画阁垂杨岸，睡起梳头。","旧游踪，招提路，重到处，满离忧。","想芙蓉湖上悠悠。","红衣狼藉，卧看少妾荡兰舟。","午风吹断江南梦，梦里菱讴。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-154","tags":[]},{"id":"poem-54f17c9728f02814f3bb1128","title":"春色满皇州","author":"封敖","dynasty":"唐","verses":["帝里春光正，葱茏喜气浮。","锦铺仙禁侧，镜写曲江头。","红蕚开萧阁，黄丝拂御楼。","千门歌吹动，九陌绮罗游。","日近风先满，仁深泽共流。","应非顦顇质，辛苦在神州。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-63f8c6d2-590e-42f7-ab7f-200d0ca8dd42","tags":[]},{"id":"poem-54f341d09d0a143e2818fb6a","title":"资圣院","author":"孙谔","dynasty":"宋","verses":["四山藏一寺，方丈压诸峰。","回首坐禅处，白云深几重。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-8dc3dc42-fd01-45be-973e-2859e3d3c387","tags":[]},{"id":"poem-54fa9c5fe9665e48235f21af","title":"诗一首","author":"张𬸦","dynasty":"唐","verses":["忽然心里爱，不觉眼中怜。","未关双眼曲，直是寸心偏。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-32ce7f3d-4314-4899-829e-044ebbed7bba","tags":[]},{"id":"poem-54ff6f8a3a7330b6220c3d14","title":"行路难","author":"聂夷中","dynasty":"唐","verses":["莫言行路难，夷狄如中国。","谓言骨肉亲，中门如异域。","出处全在人，路亦无通塞。","门前两条辙，何处去不得。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-1d8e2ba7-ba52-44c7-83d4-06dfaa2339d1","tags":[]},{"id":"poem-550edfa86ec31aa130a0dbc1","title":"戏简郑广文虔兼呈苏司业源明","author":"杜甫","dynasty":"唐","verses":["广文到官舍，系马堂阶下。","醉则骑马归，颇遭官长骂。","才名四十年，坐客寒无氊。","赖有苏司业，时时与酒钱。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-6ecd1880-117b-4442-86e0-b79993ea4ca6","tags":[]},{"id":"poem-55136c6a479156784c105b5c","title":"兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 十四","author":"易静","dynasty":"唐","verses":["论云遁，龙走有奇门。","便把铁砾喷噀酒，令军布（辛本、川本作「仰」）望必升平，云遁自相陈。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-3dd4e97f-c32c-4c7c-a554-df9ed4cb1c1f","tags":[]},{"id":"poem-551aba7b12eec455e9692b78","title":"咏古","author":"李涉","dynasty":"唐","verses":["大智思济物，道行心始休。","垂纶自消息，岁月任春秋。","纣虐武既贤，风云固可求。","顺天行杀机，所向协良谋。","况以丈人师，将济安川流。","何劳问枯骨，再取阴阳筹。","霸国不务仁，兵戈恣相酬。","空令渭水迹，千古独悠悠。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-b098ed67-25f5-43e3-ab71-d3ebec7caa1a","tags":[]},{"id":"poem-553fbfbbf66786d6aa95e97d","title":"落花","author":"李商隐","dynasty":"唐","verses":["高阁客竟去，小园花乱飞。","参差连曲陌，迢遰送斜晖。","肠断未忍扫，眼穿仍欲归。","芳心向春尽，所得是沾衣。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-da157c27-d317-4205-9cdc-a254445659fc","tags":["唐诗三百首","咏物","五言律诗","写花","抒怀","花","咏物诗"]},{"id":"poem-55403d85a1dc2e58be7ac8c8","title":"饯吉甫弟之维扬别驾","author":"柴元彪","dynasty":"宋","verses":["风樯留燕暮呢喃，行李催程春又三。","幕府来迎晁别驾，油幢曾识李淮南。","江都今古英雄会，宇宙中间化育参。","见说监州簪芍药，早乘华步趣朝骖。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-24ecf3f4-4eac-46a7-917d-1230cd69bf19","tags":[]},{"id":"poem-55435bd1b756d94abbc71fe7","title":"·","author":"王英","dynasty":"唐","verses":["。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-8e73617b-54b7-45c0-8ba8-6ed995a4852c","tags":[]},{"id":"poem-554c494ba465320eddb08ad7","title":"虞美人·楚腰蛴领团香玉","author":"阎选","dynasty":"五代","verses":["楚腰蛴领团香玉，鬓叠深深绿。","月蛾星眼笑微嚬，柳妖桃艳不胜春，晚妆匀。","水纹簟青纱帐，雾罩秋波上。","一枝娇卧醉芙蓉，袅宵不得与君同，恨忡忡。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-20","tags":[]},{"id":"poem-554f0633a4bd2bdbfb1a0b60","title":"回波词","author":"沈佺期","dynasty":"唐","verses":["回波尔时佺期，流向岭外生归。","身名已蒙齿录，袍笏未复牙绯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-bd74ae2a-94ae-4f9c-a276-a426fe90d49f","tags":[]},{"id":"poem-554fe04e0fe103b527721892","title":"题武陵洞五首 五","author":"曹唐","dynasty":"唐","verses":["渡水傍山寻绝壁，白云飞处洞天开。","仙人来往无行迹，石迳春风长绿苔。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-f3f37780-9663-48cf-9404-57f7e320d453","tags":[]},{"id":"poem-5557d057e0d589d6f4eecbe4","title":"故观文建安刘公挽诗四首  其二","author":"张栻","dynasty":"宋","verses":["国耻臣当死，公家二世心。","忍看垂绝笔，谁续断弦音。","精爽今如在，衣冠恨更深。","却嗟蜍与志，处世漫侵寻。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-a08eb917-82ac-4543-b6c4-020715ab0b22","tags":[]},{"id":"poem-555bab83c0d833ea1abc1042","title":"韦寿博书斋","author":"薛逢","dynasty":"唐","verses":["玄晏先生已白头，不随鹓鹭狎群鸥。","元卿谢免开三迳，平仲朝归卧一裘。","醉后独知殷甲子，病来犹作晋春秋。","尘缨未濯今如此，野水无情处处流。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-80277dbc-3144-475e-a8ec-e73c55eb0620","tags":[]},{"id":"poem-556e8d25f47a69db4f11a45f","title":"次韵柳郎中二咏  其二","author":"苏颂","dynasty":"宋","verses":["百幅敲冰密属连，寝甘谁复诮便便。","心闲好隠忘言几，官冷宜铺坐客毡。","乌布任宽忘道韵，绛纱徒侈怯霜天。","休嗟抛掷缣绫贵，据榻犹胜枕杫眠。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-8df77877-da87-4aa3-bcd7-02284ecbdd96","tags":[]},{"id":"poem-557770dcab1a925a71739116","title":"岭下卧疾寄刘长卿员外","author":"包佶","dynasty":"唐","verses":["唯有贫兼病，能令亲爱疎。","岁时供放逐，身世付空虚。","胫弱秋添絮，头风晓废梳。","波澜喧众口，藜藿静吾庐。","丧马思开卦，占鸮嬾发书。","十年江海隔，离恨子知予。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-fa21adbe-1de4-40d0-888d-38ebbe473d3a","tags":[]},{"id":"poem-5578ff82ea09651fc047fd04","title":"戏呈程民老","author":"华镇","dynasty":"宋","verses":["多才是处走华镳，问柳寻花九十朝。","春去光阴祇恨晚，兴来行路莫知遥。","谢安携妓情虽远，崔烈为公臭不消。","应是醉魂伤骀荡，大歌楚些为君招。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-a8d1ae9a-f29f-4b05-b4b5-86b128239e03","tags":[]},{"id":"poem-55933e15052652c853690f76","title":"浣溪沙·惆怅经年别谢娘","author":"顾敻","dynasty":"五代","verses":["惆怅经年别谢娘，月窗花院好风光，此时相望最情伤。","青鸟不来传锦字，瑶姬何处琐兰房，忍教魂梦两茫茫。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-3","tags":[]},{"id":"poem-559e1969f55cd90eb6270ed4","title":"南柯子・南歌子·腻颈凝酥白","author":"周邦彦","dynasty":"宋","verses":["腻颈凝酥白，轻衫淡粉红。","碧油凉气透帘栊。","指点庭花低映，云母屏风。","恨逐瑶琴写，书劳玉指封。","等闲赢得瘦仪容。","何事不教云雨，略下巫峰。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-520","tags":[]},{"id":"poem-55a01e60775755aee13675f9","title":"江上喜逢司空文明","author":"李端","dynasty":"唐","verses":["秦人江上见，握手泪沾巾。","落日见秋草，暮年逢故人。","非夫长作客，多病浅谋身。","台阁旧亲友，谁曾见苦辛。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-dde43147-3d4b-4c3b-b9f8-5e45db51e046","tags":[]},{"id":"poem-55a3ea298982d93f3644ad9d","title":"江南曲五首 四","author":"丁仙芝","dynasty":"唐","verses":["未晓已成妆，乘潮去茫茫。","因从京口渡，使报邵陵王。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-0db62e12-9ab8-44ca-beee-630539346037","tags":[]},{"id":"poem-55a410cd2a71107ef6598ed5","title":"感皇恩·蝴蝶满西园","author":"晁冲之","dynasty":"宋","verses":["蝴蝶满西园，啼莺无数。","水阁桥南路。","凝伫。","两行烟柳，吹落一池飞絮。","秋千斜挂起，人何处。","把酒劝君，闲愁莫诉。","留取笙歌住。","休去。","几多春色，禁得许多风雨。","海棠花谢也，君知否。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-661","tags":[]},{"id":"poem-55afe4b3816bf5b599b77645","title":"连州吟 一","author":"孟郊","dynasty":"唐","verses":["春风朝夕起，吹绿日日深。","试为连州吟，泪下不可禁。","连山何连连，连天碧岑岑。","哀猿哭花死，子规裂客心。","兰芷结新佩，潇湘遗旧音。","怨声能翦弦，坐抚零落琴。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-12bda257-d0ec-425b-ae82-044bc5bd5252","tags":[]},{"id":"poem-55c8682d44fe42860fab86be","title":"蝶恋花·秾艳娇春春婉娩","author":"王采","dynasty":"宋","verses":["秾艳娇春春婉娩。","雨惜风饶，学得宫妆浅。","爱把绿眉都不展。","无言脉脉情何限。","花下当时红粉面。","准拟新年，都向花前见。","争奈武陵人易散。","丹青传得闺中怨。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-937","tags":[]},{"id":"poem-55cb40cecb7b48f6b24090cf","title":"古意九首 七","author":"贯休","dynasty":"唐","verses":["常思谢康乐，文章有神力。","是何清风清，凛然似相识。","一种为顽嚚，得作翻经石。","一种为枯槁，得作登山屐。","永嘉为郡后，山水添鲜碧。","何当学羽翰，一去观遗迹。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-4e260c15-8a1d-43a3-ba62-4827397397e3","tags":[]},{"id":"poem-55cfd1e9595a8cd4987fe57a","title":"赋得","author":"刘长卿","dynasty":"唐","verses":["莺啼燕语报新年，马邑龙堆路几千。","家住层城临汉苑，[心]随明月到胡天。","机中锦字论长恨，楼上花枝笑独眠。","为问元戎窦车骑，何时返斾勒燕然。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-41d292d2-b752-4c30-8b6b-7b7380f2f9bd","tags":["思念","七言律诗","春天","妇女","唐诗三百首","闺怨"]},{"id":"poem-55d1087e7ebf338e6df88dca","title":"石版","author":"李咸用","dynasty":"唐","verses":["高人好自然，移得它山碧。","不磨如版平，大巧非因力。","古藓小青钱，尘中看野色。","冷倚砌花春，静伴疎篁直。","山僧若转头，如逢旧相识。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-2eca3daa-333c-4bb6-9509-5f32aa5022c0","tags":[]},{"id":"poem-55d627dc372233292662834a","title":"浣溪沙·半醉凝情卧绣茵","author":"毛熙震","dynasty":"五代","verses":["半醉凝情卧绣茵，睡容无力卸罗裙，玉笼鹦鹉厌听闻。","慵整落钗金翡翠，象梳欹鬓月生云，锦屏销幌麝烟熏。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-39","tags":[]},{"id":"poem-55d91b90ee6ff65e476a52f0","title":"荅李季兰","author":"皎然","dynasty":"唐","verses":["天女来相试，将花欲染衣。","禅心竟不起，还捧旧花归。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-18dd38a4-0ad4-4ae9-ad90-4e1a2572b486","tags":[]},{"id":"poem-55e703268f89307bbf0ca82a","title":"子夜歌·寻春须是先春早","author":"李煜","dynasty":"五代","verses":["寻春须是先春早，看花莫待花枝老。","缥色玉柔擎，醅浮盏面清。","何妨频笑粲，禁苑春归晚。","同醉与闲评，诗随羯鼓成。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-29","tags":[]},{"id":"poem-55e9a7ba1f759d9c255a0b91","title":"西津渡","author":"宋伯仁","dynasty":"宋","verses":["掀天雪浪镇三边，亿万王师未必然。","可惜大江如旧日，苦无人著祖生鞭。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-7c6e0f70-80ed-47a2-85ae-0bc012502144","tags":[]},{"id":"poem-55ea821f42007434eba63c30","title":"伤张玖秀才","author":"唐求","dynasty":"唐","verses":["铜梁剑阁几区区，十上探珠不见珠。","卞玉影沈沙草暗，骅骝声断陇城孤。","入关词客秋怀友，出户孀妻晓望夫。","吴水楚山千万里，旅魂归到故乡无。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-44e606c8-7d4a-40c4-807e-5fd3a8bd2898","tags":[]},{"id":"poem-55ebc71ad0f7cf3c8b59e1c6","title":"永明山居诗（六十九首） 十二","author":"延寿","dynasty":"唐","verses":["言行相应宜此地，空谈大隐也无端。","升沈歧路非他得，生熟根机且自看。","瞋火微烟还渐息，贪泉余润亦消干。","平生正直须甘取，虚幻门中莫自瞒。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-9c827b42-a700-45b3-863f-b65f290bba55","tags":[]},{"id":"poem-55f0df87baa6e149861868a1","title":"采桑子·土花曾染湘娥黛","author":"纳兰性德","dynasty":"清","verses":["土花曾染湘娥黛，铅泪难消。","清韵谁敲，不是犀椎是凤翘。","只应长伴端溪紫，割取秋潮。","鹦鹉偷教，方响前头见玉萧。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-212","tags":[]},{"id":"poem-55f4d9130f366fceeeb77232","title":"月诗","author":"卢仝","dynasty":"唐","verses":["金波绚彩丽初筵，玉冕（友人蒋礼鸿同志谓当作「玉菟」。","菟，同兔。","）流辉满大圆。","镜里山川同炯炯，楼前风露共娟娟。","（清康熙间仁和孙之𫘧《玉川子诗注》收此诗，云见《万花谷后集》。","）（见《锦绣万花谷后集》卷一《月》）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-0d46c47a-b5eb-4ebf-9856-3de1e69552ee","tags":[]},{"id":"poem-5627da983c1d71d00ef05feb","title":"花犯·粉墙低","author":"周邦彦","dynasty":"宋","verses":["粉墙低，梅花照眼，依然旧风味。","露痕轻缀。","疑净洗铅华，无限佳丽。","去年胜赏曾孤倚。","冰盘同宴喜。","更可惜，雪中高树，香篝熏素被。","今年对花最匆匆，相逢似有恨，依依愁悴。","吟望久，青苔上、旋看飞坠。","相将见、脆丸荐酒，人正在、空江烟浪里。","但梦想、一枝潇洒，黄昏斜照水。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-235","tags":["宋词三百首"]},{"id":"poem-562e7044a502c32bda575d2c","title":"春秋战国门 再吟","author":"周昙","dynasty":"唐","verses":["周室衰微不共匡，干戈终日互争强。","诸侯若解尊天子，列国何因次第亡。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-e81c7639-f9f2-4967-868c-9bd3f63ee8d8","tags":[]},{"id":"poem-5632ff10ff6841c2df091dda","title":"园有桃","author":"佚名","dynasty":"先秦","verses":["园有桃，其实之肴。心之忧矣，我歌且谣。不知我者，谓我士也骄。","彼人是哉，子曰何其？心之忧矣，其谁知之？其谁知之，盖亦勿思！","园有棘，其实之食。心之忧矣，聊以行国。不知我者，谓我士也罔极。","彼人是哉，子曰何其？心之忧矣，其谁知之？其谁知之，盖亦勿思！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-108","tags":[]},{"id":"poem-563ddacfc5123f05eba75008","title":"汉上偶题","author":"李涉","dynasty":"唐","verses":["谪仙唐世游兹郡，花下听歌醉眼迷。","今日汉江烟树尽，更无人唱白铜鞮。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-2386d800-7a20-48c4-a1ac-b8a1919efb93","tags":[]},{"id":"poem-5643e04b98b1a8949637f42c","title":"雨行五岭下","author":"赵文","dynasty":"宋","verses":["天地忽昼晦，四山泼墨浓。","而我行其间，宛如所翁龙。","大风吹倒人，欲避无所容。","有翼不得张，狂走急雨中。","数里乃一息，如出鲛人宫。","老树道边拜，疑我行雨工。","过午上五岭，攀缘入青空。","仰视万山巅，有气如炊笼。","下视田间白，云此锄田农。","兹行岂不苦，奇观亦已雄。","惜哉如此山，不与晓景逢。","不晓韩吏部，登华哭途穷。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-41bec625-9fa0-479a-ad42-b9b8c6d72ffe","tags":[]},{"id":"poem-5650cb3030a481c8e578efca","title":"奉赠射洪李四丈","author":"杜甫","dynasty":"唐","verses":["丈人屋上乌，人好乌亦好。","人生意气豁，不在相逢早。","南京乱初定，所向邑枯槁。","游子无根株，茅斋付秋草。","东征下月峡，挂席穷海岛。","万里须十金，妻孥未相保。","苍茫风尘际，蹭蹬骐𬴊老。","志士怀感伤，心胸已倾倒。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-f0f91037-5eae-4988-a135-88b6607ddac5","tags":[]},{"id":"poem-5655980d2db302d81b211de7","title":"浣溪沙·人意天公则甚知","author":"向子𬤇","dynasty":"宋","verses":["人意天公则甚知。","故教小雨作深悲。","桃花浑似泪胭脂。","理棹又从今日去，断肠还似去年时。","经行处处是相思。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-796","tags":[]},{"id":"poem-56591df4316782126443c857","title":"水龙吟·岁穷风雪瓢零","author":"孔夷","dynasty":"宋","verses":["岁穷风雪瓢零，望迷万里云垂冻。","红绡碎翦，凝酥繁缀，烟深霜重。","疏影沈波，暗香和月，横斜浮动。","怅别来，欲把芳菲寄远，还羌管、吹三弄。","寂寞玉人睡起，污残妆、不胜姣凤。","盈盈山馆，纷纷客路，相思谁共。","才与风流，赋称清艳，多情唯宋。","算襄王，枉被梨花瘦损，又成春梦。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-577","tags":[]},{"id":"poem-565c3f9b32f2387716196e51","title":"柳梢青·雨后天涯","author":"张镃","dynasty":"宋","verses":["雨后天涯。","微云送晚，过尽归鸦。","何处开尊，海棠亭小，飞燕风斜。","有人粲玉娇花。","更翳凤、曾游帝家。","长远身心，温柔情态，不枉多他。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-338","tags":[]},{"id":"poem-5666db3d7475dea00267d34f","title":"月夜敲砧","author":"王镃","dynasty":"宋","verses":["沉沉万籁满天星，药兔秋声处处明。","落尽灯花人欲睡，一簷桐影捣衣声。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-4faf39a2-4cd9-44f8-8c54-54f6476e89a4","tags":[]},{"id":"poem-56673df2fc12cdba675b74d2","title":"句  其九","author":"刘望之","dynasty":"宋","verses":["山遶郡楼秋过雨，月临池树晚生烟。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-b6f7451d-3dc0-4f14-928a-a2c21f47c2e9","tags":[]},{"id":"poem-56673e9d31c7dc104db06d78","title":"延福可老真赞","author":"林之奇","dynasty":"宋","verses":["浑沌凿开无限事，逍遥游后更何疑。","饶伊齐得鹏并鷃，不似当年作蝶时。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-72d3fd3e-70dc-4f29-97a8-064f298d4495","tags":[]},{"id":"poem-5681e18017785926b3b8cd19","title":"玉楼春·黄金弄色轻于粉","author":"欧阳修","dynasty":"宋","verses":["黄金弄色轻于粉。","濯濯春条如水嫩。","为缘力薄未禁风，不奈多娇长似困。","腰柔乍怯人相近。","眉小未知春有恨。","劝君著意惜芳菲，莫待行人攀折尽。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-684","tags":[]},{"id":"poem-568cccf214b20e84815d5a1f","title":"兵要望江南 占梦第二十五（京本列第十三○九首） 九","author":"易静","dynasty":"唐","verses":["将军梦，梦见大舟船。","顺水顺风帆幔顺，战之获捷独为先，快乐（辛本、川本作「不尔」）似神仙。","。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-1bef96d4-a7d1-4fce-91ee-20fd838cac5b","tags":[]},{"id":"poem-5692e30750e109727d94b1ad","title":"园林好","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["想那日身投大江，感安抚恩德怎忘？胜似嫡亲襁褓，如重遇父和娘。","奴家烧此夜香呵，愿他增福寿，永安康！想我母亲亡过之后，又亏继母呵，。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8279","tags":[]},{"id":"poem-5698fed0d7d76f721e008119","title":"赠奉律上人","author":"李德裕","dynasty":"唐","verses":["知君学地厌多闻，广渡群生出世氛。","饭色不应殊宝器，树香皆遣入禅薰。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-7be95130-83a9-468e-8ae0-358cacda75c7","tags":[]},{"id":"poem-569f8337d0086b8d4a46470d","title":"和叔崇","author":"王柏","dynasty":"宋","verses":["人心乘气机，投闲肆驰逐。","飞天忽沦渊，忘生以徇欲。","大而名节丧，甚者邦家覆。","一狂方寸乱，一安万事足。","箪瓢乐陋巷，粱肉怕书腹。","平时工用深，举动自绝俗。","伥伥无所守，有为皆碌碌。","一堕荆榛中，终身困踯躅。","世事岂有常，乌可执卷赎。","学问在我毋自弃，富贵在天毋自辱。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-bdc593cb-909c-4857-bef7-b6fa56bc8f66","tags":[]},{"id":"poem-56a6877b281aabd5005875dc","title":"郊庙歌辞 享文敬太子庙乐章 登歌","author":"陈京","dynasty":"唐","verses":["歌以德发，声以乐贵。","乐善名存，追仙礼异。","鸾旌拱修，凤鸣合吹。","神听皇慈，仲月皆至。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-87a78b1d-6698-48af-9dee-5f1ed107b418","tags":[]},{"id":"poem-56b0557664c5ee8371510f5d","title":"岭南道中","author":"曹松","dynasty":"唐","verses":["百花成实未成归，未必归心与志违。","但有壶觞资逸咏，尽交风景入清机。","半川阴雾藏高木，一道晴蜺杂落晖。","游子马前芳草合，鹧鸪啼歇又南飞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-6c5021cd-f042-408b-8dc8-9055635a8b69","tags":[]},{"id":"poem-56b567a7942cb7766a48429e","title":"臣工","author":"佚名","dynasty":"先秦","verses":["嗟嗟臣工，敬尔在公。王厘尔成，来咨来茹。嗟嗟保介，维莫之春，亦又何求？如何新畲？","于皇来牟，将受厥明。明昭上帝，迄用康年。命我众人：庤乃钱镈，奄观铚艾。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-275","tags":[]},{"id":"poem-56b5dd03495ff693eddab34d","title":"浣溪沙·波面铜花冷不收","author":"吴文英","dynasty":"宋","verses":["波面铜花冷不收。","玉人垂钓理纤钩。","月明池阁夜来秋。","江燕话归成晓别，水花红减似春休。","西风梧井叶先愁。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-193","tags":["宋词三百首"]},{"id":"poem-56bd2c7b","title":"涉江采芙蓉","author":"佚名","dynasty":"汉","verses":["涉江采芙蓉，兰泽多芳草。","采之欲遗谁？所思在远道。","还顾望旧乡，长路漫浩浩。","同心而离居，忧伤以终老。"],"enabled":true,"collection":"历代名篇","source":"《文选》卷二十九《古诗十九首》。","tags":["古诗十九首","思乡"]},{"id":"poem-56ca986a6ef78a58a625ad5b","title":"南乡子·兰棹举","author":"李珣","dynasty":"五代","verses":["兰棹举，水纹开，竞携藤笼采莲来。","回塘深处遥相见，邀同宴，绿酒一卮红上面。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-26","tags":[]},{"id":"poem-56cb2acb33becccee0309e51","title":"贺新郎·深院榴花吐","author":"刘克庄","dynasty":"宋","verses":["深院榴花吐。","画帘开、衣纨扇，午风清暑。","儿女纷纷夸结束，新样钗符艾虎。","早已有、游人观渡。","老大逢场慵作戏，任陌头、年少争旗鼓。","溪雨急，浪花舞。","灵均标致高如许。","忆生平、既纫兰佩，更怀椒糈。","谁信骚魂千载后，波底垂涎角黍。","又说是、蛟馋龙怒。","把似而今醒到了，料当年、醉死差无苦。","聊一笑，吊千古。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-54","tags":["宋词三百首"]},{"id":"poem-56cc6c0fe8a128cf916638f1","title":"好事近·小雨度微云","author":"向子𬤇","dynasty":"宋","verses":["小雨度微云，快染一天新碧。","恰到中秋佳处，是芳年华日。","冰轮莫做九分看，天意在今夕。","先占广寒风露，怕姮娥偏得。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-787","tags":[]},{"id":"poem-56d4199150879d5a2e3f11f3","title":"南乡子·翡翠䴔䴖","author":"欧阳炯","dynasty":"五代","verses":["翡翠䴔䴖，白萍香里小沙汀。","岛上阴阴秋雨色，芦花扑，数只渔船何处宿。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-7","tags":[]},{"id":"poem-56d82cebee480fbd14a35e96","title":"小重山·湖上秋来莲荡空","author":"沈晦","dynasty":"宋","verses":["湖上秋来莲荡空。","年华都付与，木芙蓉。","采菱舟子两相逢。","双媚靥，一笑与谁浓。","斜日落溟蒙。","鸳鸯飞起处，水无踪。","望湖楼上两三峰。","人不见，林外数声钟。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-935","tags":[]},{"id":"poem-56e0ffa556c9273df4f59b3c","title":"台州郡治十二诗太守尤延之命赋 节爱堂","author":"林宪","dynasty":"宋","verses":["圣人定规模，用节民自爱。","后来巧施为，民害深可慨。","先生寿正脉，吾道灿然在。","揭以榜屋梁，流风万千载。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-da4002bd-d537-4b54-9622-505cdb26cd78","tags":[]}];
